export const topicLessons: Record<string, {
  sections: { title: string; text: string }[];
  question: string;
  answer: string;
  sources: { title: string; url: string }[];
}> = {
  'ti1-2.1': {
    sections: [
      { title: 'DevOps e CAMS', text: 'DevOps integra desenvolvimento e operações para entregar mudanças pequenas e obter feedback rápido. CAMS resume Cultura (responsabilidade compartilhada), Automação (tarefas repetíveis), Medição (tempo de entrega, falhas e recuperação) e Compartilhamento (documentação e aprendizado entre equipes). DevSecOps incorpora segurança desde o planejamento, com modelagem de ameaças, revisão, análise de dependências, detecção de segredos e monitoramento após a publicação.' },
      { title: 'Da integração à produção', text: 'Na integração contínua, mudanças frequentes passam por build e testes automatizados. A entrega contínua mantém um artefato aprovado e publicável, com possibilidade de autorização manual para produção. A implantação contínua publica automaticamente cada mudança aprovada. Por exemplo, uma esteira pode testar um commit, verificar dependências, construir uma imagem, promovê-la para homologação e aguardar aprovação para produção.' },
      { title: 'Git, Docker e Kubernetes', text: 'No Git, add prepara alterações para o commit, commit registra um snapshot local, fetch atualiza referências remotas, pull busca e integra alterações e push envia commits. No Docker, um Dockerfile descreve a construção de uma imagem e um contêiner executa uma instância dessa imagem. No Kubernetes, um Pod agrupa contêineres que compartilham contexto de rede, um Deployment gerencia réplicas e atualizações de Pods e um Service fornece um endereço estável para acessar os Pods selecionados.' },
    ],
    question: 'Uma equipe testa e empacota cada mudança. A versão fica pronta para produção, mas exige aprovação humana. Depois da aprovação, três réplicas da aplicação são atualizadas. Que prática descreve a esteira e que recurso gerencia as réplicas?',
    answer: 'Entrega contínua e Deployment. A aprovação manual distingue esse cenário da implantação contínua. O Service fornece acesso estável às réplicas, enquanto o Deployment gerencia sua atualização por meio de ReplicaSets.',
    sources: [{ title: 'Git', url: 'https://git-scm.com/docs' }, { title: 'Docker', url: 'https://docs.docker.com/get-started/docker-concepts/' }, { title: 'Kubernetes', url: 'https://kubernetes.io/docs/concepts/workloads/controllers/deployment/' }],
  },
  'ti1-2.2': {
    sections: [
      { title: 'Monólito, microsserviços e SOA', text: 'Um monólito é implantado como uma unidade e pode ter módulos internos bem definidos. Microsserviços organizam capacidades de negócio em serviços implantáveis de modo independente. Isso permite escalar partes do sistema separadamente e aumenta o custo de comunicação, observabilidade e coordenação de dados. SOA integra capacidades por contratos de serviço e pode usar mediação e orquestração. Barramento é uma opção arquitetural em SOA. Em sistemas distribuídos, estabeleça limites de tempo, trate falhas parciais e use idempotência para evitar efeitos duplicados em novas tentativas.' },
      { title: 'REST e SOAP', text: 'REST é um estilo arquitetural com restrições como cliente-servidor, comunicação sem estado de sessão entre requisições, cache, interface uniforme e camadas. Em HTTP, GET é seguro e idempotente, PUT e DELETE são idempotentes e POST pode criar recursos ou executar operações. Um DELETE repetido pode responder 404 após o primeiro sucesso e manter o mesmo efeito pretendido. SOAP é um protocolo de mensagens XML com Envelope, Header opcional, Body e estrutura Fault para erros. WSDL pode descrever contratos. JSON é uma escolha frequente em APIs REST.' },
      { title: 'Padrões de projeto', text: 'Padrões criacionais tratam da criação de objetos. Factory Method delega a decisão de qual classe concreta instanciar. Padrões estruturais organizam composição. Adapter traduz interfaces incompatíveis e Facade simplifica o acesso a um subsistema. Padrões comportamentais organizam colaboração. Strategy permite alternar algoritmos, como regras de cálculo de multa. Observer notifica interessados quando um estado muda, como assinantes de uma mudança no andamento de um processo.' },
    ],
    question: 'Um módulo deve trocar a regra de cálculo da multa conforme o tipo de infração e também consumir um serviço legado com uma interface incompatível. Que padrões se aplicam?',
    answer: 'Strategy encapsula as regras de cálculo sob uma interface comum. Adapter traduz as chamadas esperadas pelo módulo para a interface do legado. São problemas diferentes, um de comportamento e outro de compatibilidade estrutural.',
    sources: [{ title: 'Dissertação de Roy Fielding sobre REST', url: 'https://ics.uci.edu/~fielding/pubs/dissertation/rest_arch_style.htm' }, { title: 'SOAP 1.2 · W3C', url: 'https://www.w3.org/TR/soap12-part1/' }, { title: 'Semântica HTTP · RFC 9110', url: 'https://www.rfc-editor.org/rfc/rfc9110' }],
  },
  'ti1-2.3': {
    sections: [
      { title: 'Scrum', text: 'Scrum usa ciclos de até um mês chamados Sprints. O Product Owner maximiza valor e responde pela gestão eficaz do Product Backlog. Developers planejam e executam o trabalho para criar um incremento utilizável. O Scrum Master atua sobre a eficácia do time e a aplicação de Scrum. Sprint Planning define por que a Sprint tem valor, o que pode ser feito e como. Daily Scrum permite aos Developers inspecionar o progresso rumo ao objetivo. Sprint Review inspeciona o resultado com partes interessadas. Retrospectiva planeja melhorias de qualidade e eficácia.' },
      { title: 'Artefatos e compromissos', text: 'O Product Backlog tem como compromisso o Objetivo do Produto. O Sprint Backlog associa itens selecionados e plano de execução ao Objetivo da Sprint. O Incremento deve cumprir a Definição de Pronto. Pode haver vários incrementos numa Sprint e a Review não funciona como uma autorização obrigatória para entregá-los.' },
      { title: 'Kanban e XP', text: 'Kanban explicita o fluxo, controla o trabalho em progresso e usa um sistema puxado. Se a revisão está no limite, liberar capacidade nessa etapa favorece o fluxo. Throughput mede itens concluídos por período e tempo de ciclo mede o intervalo entre início e conclusão. XP dá ênfase a práticas técnicas como programação em pares, integração contínua, refatoração, design simples e desenvolvimento orientado a testes. No TDD, escreva um teste que falha, implemente o mínimo para passar e melhore o código preservando o comportamento.' },
    ],
    question: 'Na Sprint, o time quer discutir com usuários o que mudou no produto e depois avaliar internamente seu próprio processo. Há ainda um gargalo na revisão de código. Quais práticas atendem a cada objetivo?',
    answer: 'Use a Sprint Review para inspecionar o resultado com usuários e adaptar o trabalho futuro. Use a Retrospectiva para planejar melhorias do processo. No Kanban, explicite o limite de trabalho em progresso na revisão e ajude a liberar capacidade antes de puxar mais trabalho.',
    sources: [{ title: 'Guia do Scrum', url: 'https://scrumguides.org/scrum-guide.html' }, { title: 'The Kanban Guide', url: 'https://kanbanguides.org/english/' }, { title: 'Extreme Programming · Agile Alliance', url: 'https://agilealliance.org/glossary/xp/' }],
  },
  'trans3-1': {
    sections: [
      { title: 'Centro e dispersão', text: 'A média aritmética divide a soma pela quantidade de observações. A ponderada divide a soma dos produtos entre valores e pesos pela soma dos pesos. A mediana é o valor central após ordenar os dados, ou a média dos dois centrais quando a quantidade é par. A moda é o valor mais frequente. A variância mede os desvios quadráticos em relação à média. Divida a soma desses desvios por N para descrever uma população e por n−1 para estimar a variância populacional a partir de uma amostra aleatória. O desvio padrão é a raiz da variância e volta à unidade original.' },
      { title: 'Tabelas e gráficos', text: 'A frequência relativa divide a frequência absoluta pelo total. Em uma tabela cruzada, escolha o denominador de acordo com o grupo pedido. Use barras para comparar categorias, histograma para frequências de uma variável quantitativa agrupada e linha para acompanhar uma série temporal. Em histogramas com classes de larguras diferentes, a área representa a frequência e a altura representa densidade. Verifique unidade, período, fonte e escala antes de interpretar um gráfico.' },
    ],
    question: 'Os tempos de espera foram 2, 4 e 12 minutos. Calcule média, mediana e variância populacional.',
    answer: 'A média é 6 e a mediana é 4 minutos. A variância é (16 + 4 + 36)/3 = 56/3 minutos quadrados. A espera de 12 minutos puxa a média para cima.',
    sources: [{ title: 'Manual de métodos estatísticos do NIST', url: 'https://www.itl.nist.gov/div898/handbook/' }],
  },
  'trans3-2': {
    sections: [
      { title: 'Eventos e probabilidade', text: 'Use P(A ∪ B) = P(A) + P(B) − P(A ∩ B) para evitar contar a interseção duas vezes. A condicional P(A | B) é P(A ∩ B)/P(B) quando P(B) é positiva. Se A e B são independentes, a interseção tem probabilidade P(A)P(B). Eventos mutuamente exclusivos têm interseção vazia. O teorema de Bayes permite inverter uma condicional usando P(A | B) = P(B | A)P(A)/P(B).' },
      { title: 'Distribuições básicas', text: 'Bernoulli representa um ensaio binário. Binomial conta sucessos em n ensaios independentes com probabilidade constante p, com média np e variância np(1−p). Poisson modela contagens com taxa constante em um intervalo e média igual à variância no modelo. Uniforme contínua atribui a mesma densidade em todo o intervalo. A normal é contínua e simétrica. Para usar a normal padrão, converta x em z = (x−μ)/σ.' },
    ],
    question: 'Quatro inspeções independentes têm probabilidade de irregularidade de 20% cada. Qual a chance de detectar pelo menos uma?',
    answer: 'Use o complementar. A chance de nenhuma irregularidade é 0,8⁴. Logo a chance de pelo menos uma é 1−0,4096 = 59,04%.',
    sources: [{ title: 'Distribuições de probabilidade · NIST', url: 'https://www.itl.nist.gov/div898/handbook/eda/section3/eda36.htm' }],
  },
  'trans3-3': {
    sections: [
      { title: 'Amostragem e inferência', text: 'Defina a população, a unidade e a lista de seleção. Na amostragem aleatória simples, selecione unidades aleatoriamente. Na estratificada, sorteie dentro de cada estrato, como região. Por conglomerados, sorteie grupos, como escolas. Na sistemática, use início aleatório e intervalo fixo, observando possíveis ciclos na lista. Aumentar uma amostra de conveniência pode reduzir parte da variabilidade e conservar o viés de seleção. Um intervalo de confiança expressa a incerteza amostral sob as hipóteses do método.' },
      { title: 'Testes de hipóteses', text: 'Defina H₀, H₁ e o nível de significância antes da análise. O valor p mede, sob H₀, a probabilidade de observar uma estatística tão ou mais extrema que a obtida. Rejeite H₀ se p ≤ α. Erro tipo I é rejeitar uma hipótese nula verdadeira. Erro tipo II é deixar de rejeitar uma hipótese nula falsa. Poder é a probabilidade de detectar o efeito especificado. Compare tamanho do efeito e intervalo de confiança para julgar a importância prática.' },
      { title: 'Pesquisa social', text: 'Pesquisa quantitativa mede variáveis e estima magnitudes ou associações. Pesquisa qualitativa investiga experiências e mecanismos usando entrevistas, observação e análise de documentos. Codificar relatos permite reunir temas e comparar casos. Métodos mistos podem medir a evasão de um programa por região e entrevistar participantes para investigar as barreiras que produziram esse padrão.' },
    ],
    question: 'Um estudo obteve p = 0,03 para a diferença de atendimento entre dois grupos. Qual é a decisão a 5% e a 1%?',
    answer: 'Rejeite H₀ a 5%. A 1%, o resultado é insuficiente para rejeitar H₀. Para avaliar a importância da diferença, verifique sua magnitude, o intervalo de confiança e o desenho do estudo.',
    sources: [{ title: 'Manual de métodos estatísticos do NIST', url: 'https://www.itl.nist.gov/div898/handbook/' }],
  },
  'trans3-4': {
    sections: [
      { title: 'Planejamento e monitoramento', text: 'Use o diagnóstico para definir o problema, a população e a linha de base. Relacione recursos, atividades, entregas e resultados em uma cadeia lógica. Em fiscalização, orçamento é insumo, inspeções realizadas são entregas e redução da reincidência é resultado. Registre fórmula, fonte, periodicidade, meta e responsável por cada indicador. Compare taxas com denominadores consistentes e desagregue por região quando diferenças locais forem relevantes.' },
      { title: 'Avaliação de impacto', text: 'Monitoramento acompanha a execução. Avaliação de processo examina a implementação. Avaliação de impacto estima a diferença entre o resultado observado e o que ocorreria sem a política. Um grupo sorteado fornece uma comparação quando o desenho e a execução sustentam sua validade. Em diferenças em diferenças, subtraia a mudança do grupo de comparação da mudança do grupo tratado. A interpretação depende de tendências paralelas na ausência da intervenção e de outras hipóteses do desenho.' },
    ],
    question: 'Após uma política, o atendimento subiu de 50% para 65% no grupo tratado e de 45% para 55% no grupo de comparação. Qual é a estimativa por diferenças em diferenças?',
    answer: 'A estimativa é (65−50)−(55−45) = 5 pontos percentuais. A interpretação causal depende da validade do grupo de comparação e das hipóteses do desenho.',
    sources: [{ title: 'Impact Evaluation in Practice · Banco Mundial', url: 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice' }],
  },
  'dir0-1': {
    sections: [
      { title: 'Constituição e poder constituinte', text: 'Constituição é a norma fundamental que organiza o Estado, distribui competências, limita o poder e reconhece direitos. O preâmbulo orienta a interpretação, mas o STF decidiu que não tem força normativa autônoma. Os elementos constitucionais são usualmente agrupados em orgânicos, limitativos, socioideológicos, de estabilização e formais de aplicabilidade. O poder constituinte originário cria nova ordem, é inicial e juridicamente incondicionado. O derivado reformador altera o texto conforme o procedimento e limites do art. 60. Não se pode abolir a forma federativa, o voto direto, secreto, universal e periódico, a separação dos Poderes ou direitos e garantias individuais.' },
      { title: 'Interpretação constitucional', text: 'A unidade da Constituição orienta interpretar normas como conjunto. A máxima efetividade busca realizar direitos. A concordância prática procura harmonizar princípios em conflito. A força normativa exige interpretação que preserve eficácia. A interpretação conforme escolhe, entre sentidos possíveis, o compatível com a Constituição, sem reescrever o texto contra seu sentido inequívoco.' },
    ],
    question: 'Uma emenda aprovada por três quintos dos votos, em dois turnos em cada Casa, pretende extinguir a separação dos Poderes. O procedimento formal basta?',
    answer: 'Não. Além dos requisitos formais do art. 60, a separação dos Poderes é cláusula pétrea e não pode ser abolida por emenda.',
    sources: [{ title: 'Constituição Federal atualizada · Senado', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }],
  },
  'dir0-2': {
    sections: [
      { title: 'Controle concentrado no STF', text: 'A ADI impugna lei ou ato normativo federal ou estadual em face da Constituição Federal. A ADC busca afirmar a constitucionalidade de lei ou ato normativo federal, diante de controvérsia judicial relevante. A ADPF evita ou repara lesão a preceito fundamental por ato do poder público, inclusive quando não houver outro meio eficaz, observada a subsidiariedade. São legitimados os indicados no art. 103. Alguns precisam demonstrar pertinência temática, como governador e confederação sindical. Em regra, as decisões definitivas de mérito produzem eficácia contra todos e efeito vinculante para os demais órgãos do Judiciário e a administração pública.' },
      { title: 'Reserva de plenário e efeitos', text: 'O tribunal só declara a inconstitucionalidade pelo voto da maioria absoluta de seus membros ou do órgão especial, conforme art. 97. A cláusula de reserva de plenário não impede órgão fracionário de aplicar precedente do plenário ou do STF. O STF pode modular efeitos por segurança jurídica ou excepcional interesse social, com quórum de dois terços na ADI e ADC.' },
    ],
    question: 'Uma lei municipal é questionada diretamente perante a Constituição Federal por ADI no STF. Qual ação pode, em tese, examinar o ato municipal quanto a preceito fundamental?',
    answer: 'ADPF, se houver lesão a preceito fundamental e inexistir outro meio eficaz para sanar a lesividade. A subsidiariedade deve ser demonstrada.',
    sources: [{ title: 'Lei 9.868/1999 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9868.htm' }, { title: 'Lei 9.882/1999 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9882.htm' }],
  },
  'dir0-3': {
    sections: [
      { title: 'Federação e bens', text: 'A organização político-administrativa compreende União, Estados, Distrito Federal e Municípios, todos autônomos nos termos constitucionais. Autonomia envolve auto-organização, autogoverno, autoadministração e legislação dentro de suas competências. Soberania pertence à República Federativa do Brasil. A União tem bens enumerados no art. 20. Entre eles estão terras devolutas indispensáveis à defesa, recursos minerais e potenciais de energia hidráulica. Terras devolutas estaduais pertencem aos Estados, ressalvadas as hipóteses constitucionais da União.' },
      { title: 'Repartição de competências', text: 'A União legisla privativamente sobre matérias enumeradas no art. 22, com delegação aos Estados por lei complementar sobre questões específicas. A competência concorrente do art. 24 cabe à União, Estados e Distrito Federal. A União estabelece normas gerais e os Estados suplementam. Sem norma geral federal, os Estados exercem competência legislativa plena para atender peculiaridades. A superveniência da norma federal suspende a eficácia da lei estadual no que lhe for contrário. Municípios legislam sobre interesse local e suplementam legislação federal e estadual.' },
    ],
    question: 'Se não existir norma geral federal sobre matéria de competência concorrente, pode o Estado legislar?',
    answer: 'Sim. O Estado exerce competência legislativa plena para atender suas peculiaridades, conforme art. 24, §3º. A norma geral federal superveniente suspende a eficácia estadual apenas no ponto de conflito.',
    sources: [{ title: 'Constituição Federal atualizada · Senado', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }],
  },
  'dir0-4': {
    sections: [
      { title: 'Estrutura e funções', text: 'O Poder Legislativo federal é exercido pelo Congresso Nacional, composto pela Câmara dos Deputados, que representa o povo, e pelo Senado Federal, que representa os Estados e o Distrito Federal. As Assembleias Legislativas exercem o Legislativo estadual. O Congresso reúne-se em sessão legislativa ordinária de 2 de fevereiro a 17 de julho e de 1º de agosto a 22 de dezembro, observadas as regras constitucionais sobre transferência das reuniões. A função típica é legislar e fiscalizar. Há funções atípicas, como administrar seus serviços e julgar autoridades nos casos constitucionais.' },
      { title: 'Processo legislativo e fiscalização', text: 'O processo legislativo inclui emendas à Constituição, leis complementares e ordinárias, leis delegadas, medidas provisórias, decretos legislativos e resoluções. A Constituição define iniciativa, votação, sanção ou veto e promulgação. O Congresso fiscaliza atos do Executivo, com auxílio do Tribunal de Contas da União. Comissões podem discutir projetos, convocar ministros e realizar audiências. Imunidades parlamentares protegem o exercício do mandato nos limites constitucionais.' },
    ],
    question: 'O Tribunal de Contas da União integra o Poder Legislativo?',
    answer: 'Não. É órgão autônomo de controle externo que auxilia o Congresso Nacional. Não integra a estrutura orgânica do Legislativo, Executivo ou Judiciário.',
    sources: [{ title: 'Constituição Federal atualizada · Senado', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }],
  },
  'dir0-5': {
    sections: [
      { title: 'Jurisdição e órgãos', text: 'Jurisdição é a função estatal de aplicar o direito ao caso concreto com autoridade. O art. 92 enumera os órgãos do Judiciário, incluindo STF, CNJ, STJ, Justiça Federal, do Trabalho, Eleitoral, Militar e dos Estados e Distrito Federal. O CNJ controla a atuação administrativa e financeira do Judiciário e o cumprimento dos deveres funcionais dos juízes, sem exercer jurisdição recursal sobre decisões judiciais.' },
      { title: 'Competência constitucional', text: 'O STF guarda a Constituição e julga, entre outras hipóteses, ações diretas de inconstitucionalidade e autoridades nos casos previstos. O STJ uniformiza a interpretação da legislação federal infraconstitucional. A Justiça Federal julga causas em que a União, autarquia ou empresa pública federal figure, ressalvadas exceções constitucionais. A Justiça estadual tem competência residual. A competência da Justiça do Trabalho decorre do art. 114 e a da Eleitoral e Militar de seus dispositivos próprios.' },
    ],
    question: 'Uma parte insatisfeita com sentença judicial pede ao CNJ que a reforme. O Conselho pode funcionar como instância recursal?',
    answer: 'Não. O CNJ exerce controle administrativo e disciplinar nos limites constitucionais, sem substituir os recursos judiciais.',
    sources: [{ title: 'Constituição Federal atualizada · Senado', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }],
  },
  'dir0-6': {
    sections: [
      { title: 'Administração e princípios', text: 'A administração direta é formada pelos órgãos dos entes federativos. A indireta compreende entidades com personalidade jurídica própria, como autarquias, fundações públicas, empresas públicas e sociedades de economia mista. O art. 37 impõe legalidade, impessoalidade, moralidade, publicidade e eficiência. Concurso é a regra de ingresso em cargo ou emprego, ressalvados cargos em comissão e hipóteses constitucionais. A investidura em cargo ou emprego depende de aprovação prévia no concurso adequado.' },
      { title: 'Servidores e regime constitucional', text: 'O regime dos servidores varia conforme o ente e a lei aplicável. Cargo público é conjunto de atribuições criado por lei, ocupado por servidor estatutário. Emprego público é vínculo contratual trabalhista. Função é conjunto de atribuições, inclusive funções de confiança exercidas exclusivamente por servidores efetivos. A estabilidade é adquirida após três anos de efetivo exercício e avaliação especial, para servidor nomeado por concurso para cargo efetivo. Perda do cargo está sujeita às hipóteses constitucionais do art. 41.' },
    ],
    question: 'Empregado de empresa pública aprovado em concurso adquire estabilidade do art. 41?',
    answer: 'Não. O art. 41 prevê estabilidade para servidor nomeado para cargo efetivo após concurso. Empregado público ocupa emprego, com regime trabalhista.',
    sources: [{ title: 'Constituição Federal atualizada · Senado', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }],
  },
  'dir0-7': {
    sections: [
      { title: 'Funções essenciais à Justiça', text: 'O Ministério Público é instituição permanente, essencial à função jurisdicional, incumbida da defesa da ordem jurídica, do regime democrático e dos interesses sociais e individuais indisponíveis. Tem autonomia funcional e administrativa e princípios de unidade, indivisibilidade e independência funcional. A Advocacia Pública representa judicial e extrajudicialmente os entes e presta consultoria jurídica, conforme a Constituição. A Defensoria Pública presta orientação jurídica e defesa integral e gratuita aos necessitados, com autonomia funcional e administrativa.' },
      { title: 'Garantias e diferenças', text: 'O Ministério Público não integra o Judiciário e não julga. Advogados públicos defendem juridicamente o ente público e orientam sua atuação. A Defensoria promove direitos dos necessitados, individual e coletivamente. A advocacia privada é indispensável à administração da justiça e inviolável nos limites da lei. As funções e garantias de cada instituição são distintas e não intercambiáveis.' },
    ],
    question: 'Qual instituição tem atribuição constitucional de defesa dos necessitados e orientação jurídica integral e gratuita?',
    answer: 'A Defensoria Pública, nos termos do art. 134 da Constituição.',
    sources: [{ title: 'Constituição Federal atualizada · Senado', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }],
  },
  'dir0-8': {
    sections: [
      { title: 'Direitos fundamentais', text: 'O art. 5º protege vida, liberdade, igualdade, segurança e propriedade. Direitos não são absolutos e conflitos exigem ponderação fundamentada, preservando seu núcleo essencial. Garantias incluem habeas corpus para liberdade de locomoção, mandado de segurança para direito líquido e certo não protegido por habeas corpus ou habeas data, habeas data para informações pessoais e mandado de injunção diante da falta de norma que inviabilize direito constitucional. A ação popular permite ao cidadão buscar anulação de ato lesivo aos bens protegidos no art. 5º, LXXIII.' },
      { title: 'Difusos, coletivos e sociais', text: 'Interesses difusos são transindividuais, indivisíveis e pertencem a pessoas indeterminadas ligadas por circunstâncias de fato. Coletivos em sentido estrito são indivisíveis e vinculados a grupo, categoria ou classe por relação jurídica base. Individuais homogêneos são direitos individuais com origem comum e tratamento coletivo possível. O art. 6º lista direitos sociais como educação, saúde, trabalho, moradia, transporte, segurança e previdência. A aplicação e a exigibilidade dependem do direito e do contexto constitucional e legal.' },
    ],
    question: 'Falta norma regulamentadora que torna inviável exercer direito constitucional. Qual garantia é apropriada?',
    answer: 'Mandado de injunção, previsto no art. 5º, LXXI. Ele enfrenta a omissão normativa que inviabiliza o exercício de direitos e liberdades constitucionais ou prerrogativas ligadas à nacionalidade, soberania e cidadania.',
    sources: [{ title: 'Constituição Federal atualizada · Senado', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }, { title: 'Lei 13.300/2016 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13300.htm' }],
  },
  'dir0-9': {
    sections: [
      { title: 'Direito à educação', text: 'A educação é direito de todos e dever do Estado e da família, promovida com colaboração da sociedade. O art. 206 estabelece princípios como igualdade de condições para acesso e permanência, liberdade de aprender e ensinar, pluralismo, gratuidade do ensino público em estabelecimentos oficiais, valorização dos profissionais e gestão democrática na forma da lei. O dever estatal inclui educação básica obrigatória e gratuita dos quatro aos dezessete anos e atendimento educacional especializado, preferencialmente na rede regular.' },
      { title: 'Competências e financiamento', text: 'União, Estados, Distrito Federal e Municípios organizam seus sistemas em regime de colaboração. Municípios atuam prioritariamente na educação infantil e ensino fundamental. Estados e Distrito Federal atuam prioritariamente no ensino fundamental e médio. A União exerce função redistributiva e supletiva e organiza o sistema federal. A Constituição fixa percentuais mínimos de aplicação da receita de impostos em manutenção e desenvolvimento do ensino.' },
    ],
    question: 'A gratuidade constitucional do ensino público oficial alcança apenas a educação básica?',
    answer: 'Não. O princípio do art. 206, IV, prevê gratuidade do ensino público em estabelecimentos oficiais, sem restringi-la à educação básica.',
    sources: [{ title: 'Constituição Federal atualizada · Senado', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }, { title: 'Lei de Diretrizes e Bases · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9394.htm' }],
  },
  'dir0-10': {
    sections: [
      { title: 'Ciência, tecnologia e inovação', text: 'Os arts. 218 a 219-B determinam que o Estado promova e incentive desenvolvimento científico, pesquisa, capacitação científica e tecnológica e inovação. A pesquisa científica básica e tecnológica recebe tratamento prioritário, considerando o bem público e o progresso da ciência, tecnologia e inovação. A pesquisa tecnológica volta-se preponderantemente à solução dos problemas brasileiros e ao desenvolvimento do sistema produtivo nacional e regional.' },
      { title: 'Cooperação e proteção', text: 'O Estado deve apoiar formação de recursos humanos em ciência, pesquisa, tecnologia e inovação, inclusive por meios de extensão tecnológica e apoio a atividades de inovação nas empresas. Entes públicos podem cooperar entre si e com instituições públicas e privadas para projetos de pesquisa, desenvolvimento científico e tecnológico e inovação. A Constituição também prevê o Sistema Nacional de Ciência, Tecnologia e Inovação em regime de colaboração.' },
    ],
    question: 'A Constituição trata a pesquisa tecnológica como atividade sem relação com problemas nacionais?',
    answer: 'Não. O art. 218, §2º, orienta a pesquisa tecnológica preponderantemente à solução dos problemas brasileiros e ao desenvolvimento do sistema produtivo nacional e regional.',
    sources: [{ title: 'Constituição Federal atualizada · Senado', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }],
  },
  'dir1-1': {
    sections: [
      { title: 'Conceito e objeto', text: 'Direito Administrativo é o ramo do direito público que organiza a função administrativa, seus órgãos e agentes, e disciplina a atuação estatal voltada a fins públicos. Seu objeto alcança administração direta e indireta, serviços públicos, poder de polícia, atos, contratos, bens, agentes, processo e controle da Administração. A função administrativa é exercida predominantemente pelo Executivo, mas também pelos demais Poderes em suas atividades internas. O critério funcional ajuda a distingui-la das funções legislativa e jurisdicional.' },
      { title: 'Regime jurídico e fontes', text: 'O regime jurídico administrativo reúne prerrogativas necessárias à atuação pública e sujeições destinadas a proteger o interesse coletivo. A Constituição e as leis são fontes primárias. Regulamentos detalham a execução da lei dentro dos limites da competência. Jurisprudência, doutrina e costumes administrativos orientam interpretação, sem permitir que a Administração contrarie a lei. O interesse público deve ser compreendido conforme a Constituição, os direitos fundamentais e a finalidade legal.' },
    ],
    question: 'A Câmara Municipal realiza concurso para seus servidores. Essa atividade é administrativa mesmo sendo praticada pelo Legislativo?',
    answer: 'Sim. A separação dos Poderes não impede que cada Poder exerça atipicamente função administrativa para organizar seus serviços e gerir seus agentes.',
    sources: [{ title: 'Constituição Federal · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }],
  },
  'dir1-2': {
    sections: [
      { title: 'Elementos e atributos', text: 'O ato administrativo é manifestação unilateral da Administração, ou de quem exerça função pública, que produz efeitos jurídicos sob regime público. Analise competência, finalidade, forma, motivo e objeto. Competência, finalidade e forma vinculada não ficam disponíveis ao agente. Motivo são os pressupostos de fato e de direito. Objeto é o efeito jurídico. Presunção de legitimidade admite prova contrária. Imperatividade impõe obrigações sem consentimento em atos que a comportam. Autoexecutoriedade existe quando a lei autoriza ou a urgência a justifica. Tipicidade exige correspondência com figuras legais.' },
      { title: 'Vinculação, discricionariedade e espécies', text: 'No ato vinculado, a lei predetermina os elementos. Na discricionariedade, a lei permite escolha legítima de motivo ou objeto dentro dos limites legais, sujeita a controle de legalidade, finalidade e proporcionalidade. Atos normativos, ordinatórios, negociais, enunciativos e punitivos são classificações didáticas. Licença costuma ser vinculada quando preenchidos os requisitos. Autorização costuma ser discricionária e precária, conforme o regime legal aplicável.' },
      { title: 'Extinção e controle', text: 'Anulação retira ato ilegal e pode ocorrer pela Administração ou pelo Judiciário. Revogação retira ato válido por conveniência e oportunidade, respeitados direitos adquiridos e os limites legais. A Administração deve observar decadência para anular atos favoráveis, salvo má-fé, conforme a lei aplicável. Convalidação pode sanar defeitos sanáveis, sem lesão ao interesse público ou a terceiros. Mérito administrativo não autoriza violar direitos nem substituir requisito legal.' },
    ],
    question: 'Uma licença vinculada foi concedida corretamente, mas a Administração depois considera inconveniente mantê-la. Cabe revogação?',
    answer: 'Em regra, a revogação recai sobre ato discricionário válido por conveniência e oportunidade. A Administração deve examinar o regime da licença, eventual direito adquirido e a lei específica. Ilegalidade leva à anulação, não à revogação.',
    sources: [{ title: 'Lei 9.784/1999 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9784.htm' }],
  },
  'dir1-3': {
    sections: [
      { title: 'Administração direta e indireta', text: 'A direta compreende os entes federativos e seus órgãos sem personalidade jurídica própria. A indireta reúne entidades com personalidade própria criadas ou autorizadas por lei para atividades administrativas. Autarquia é criada diretamente por lei para atividade típica estatal. Empresa pública tem capital integralmente público e pode assumir formas societárias diversas. Sociedade de economia mista é sociedade anônima com maioria do capital votante público. Fundação pública tem patrimônio personalizado para finalidade social definida, sob regime público ou privado conforme sua instituição e a lei.' },
      { title: 'Descentralização, tutela e fundações', text: 'Desconcentração distribui competências dentro da mesma pessoa jurídica e cria órgãos. Descentralização transfere a execução ou titularidade nos limites legais para outra pessoa. A tutela ou supervisão ministerial controla a entidade conforme a lei, sem hierarquia entre entidade e ente instituidor. Fundação pública de direito privado integra a Administração indireta, embora seu regime combine normas públicas e privadas. Fundação privada nasce por iniciativa privada e não integra a Administração apenas por receber apoio estatal.' },
    ],
    question: 'A secretaria cria uma coordenadoria dentro de sua estrutura. Ocorreu descentralização?',
    answer: 'Não. A criação de órgão dentro da mesma pessoa jurídica é desconcentração. Descentralização envolve outra pessoa jurídica ou delegação prevista em lei.',
    sources: [{ title: 'Decreto-Lei 200/1967 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm' }],
  },
  'dir1-4': {
    sections: [
      { title: 'Serviço público e princípios', text: 'Serviço público é atividade destinada a satisfazer necessidades coletivas sob responsabilidade estatal e disciplina jurídica pública, diretamente ou por delegação. Continuidade, igualdade dos usuários, mutabilidade e eficiência orientam a prestação. A classificação em serviços próprios e impróprios, gerais e individuais, exclusivos e não exclusivos auxilia o estudo, mas o regime depende da Constituição e da lei. A titularidade pública não se confunde com a execução por particular.' },
      { title: 'Concessão, permissão e autorização', text: 'A concessão transfere a execução por prazo e por conta e risco do concessionário, precedida de licitação e formalizada em contrato. A permissão de serviço público é delegação contratual precária a pessoa física ou jurídica, precedida de licitação, conforme a Lei 8.987/1995. O usuário tem direitos de serviço adequado e participação nos canais previstos em lei. Autorização pode permitir atividade ou uso em hipóteses legais, geralmente com precariedade, e não equivale automaticamente à concessão.' },
    ],
    question: 'Uma empresa opera serviço público por concessão. O Estado deixa de ser titular e perde o dever de fiscalizar?',
    answer: 'Não. A delegação transfere a execução nos termos legais, mas o poder concedente mantém a titularidade pública e o dever de regulamentar e fiscalizar.',
    sources: [{ title: 'Lei 8.987/1995 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l8987cons.htm' }],
  },
  'dir1-5': {
    sections: [
      { title: 'Poderes administrativos', text: 'Poder hierárquico organiza e distribui funções, permite ordens, revisão e delegação ou avocação nos limites legais. Poder disciplinar apura infrações e aplica sanções a pessoas sujeitas à disciplina administrativa, com devido processo. Poder regulamentar expede atos gerais para fiel execução da lei, sem criar obrigações primárias fora da autorização constitucional. Poder de polícia condiciona ou restringe direitos e atividades em favor de interesses coletivos, observada a lei.' },
      { title: 'Atributos e limites do poder de polícia', text: 'Atributos frequentemente identificados são discricionariedade, autoexecutoriedade e coercibilidade, mas nem todo ato reúne todos. Cobrança de multa não pode ser executada diretamente sobre o patrimônio sem via própria. Taxa de polícia exige exercício regular do poder de polícia conforme a Constituição e o CTN. Toda atuação está sujeita à legalidade, motivação, proporcionalidade, contraditório quando cabível e controle judicial.' },
    ],
    question: 'A Administração aplica multa e, sem processo judicial, retira dinheiro da conta do autuado. A autoexecutoriedade autoriza isso?',
    answer: 'Não. A imposição da multa pode decorrer do poder de polícia, mas a cobrança forçada do crédito segue a via legal de execução, com controle judicial.',
    sources: [{ title: 'Código Tributário Nacional · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l5172compilado.htm' }],
  },
  'dir1-6': {
    sections: [
      { title: 'Responsabilidade objetiva do Estado', text: 'O art. 37, §6º, da Constituição prevê responsabilidade objetiva das pessoas jurídicas de direito público e das pessoas jurídicas de direito privado prestadoras de serviço público por danos que seus agentes, nessa qualidade, causem a terceiros. A vítima demonstra conduta estatal, dano e nexo causal, sem precisar provar culpa do agente. Caso fortuito externo, culpa exclusiva da vítima e fato exclusivo de terceiro podem romper o nexo. Culpa concorrente pode reduzir a indenização. Omissões exigem análise do dever específico de agir e da jurisprudência aplicável.' },
      { title: 'Regresso e agente', text: 'A pessoa jurídica indeniza o terceiro quando presentes os pressupostos. A ação regressiva contra o agente exige dolo ou culpa. São relações distintas: a vítima demanda o ente responsável e a Administração busca ressarcimento do agente após demonstrar responsabilidade subjetiva. A responsabilidade pode coexistir nas esferas civil, administrativa e penal, com regras próprias.' },
    ],
    question: 'Após indenizar vítima, o Estado pode cobrar automaticamente o valor integral do servidor que praticou o ato?',
    answer: 'Não automaticamente. A ação regressiva requer comprovação de dolo ou culpa do agente e o devido processo. A responsabilidade objetiva perante a vítima não elimina essa exigência.',
    sources: [{ title: 'Constituição Federal · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }],
  },
  'dir1-7': {
    sections: [
      { title: 'Processo administrativo', text: 'Processo administrativo organiza a atuação estatal para decidir, controlar e proteger direitos. A Constituição assegura contraditório e ampla defesa em processo administrativo sancionador e em situações que afetem direitos. A Lei Federal 9.784/1999 disciplina a Administração Pública Federal e pode servir de referência, mas não substitui lei estadual própria. No Mato Grosso, a Lei 7.692/2002 regula o processo administrativo estadual.' },
      { title: 'Princípios, fases e requisitos', text: 'A Lei 7.692/2002 deve ser lida para competências, forma, comunicação, instrução, prova, decisão, recursos e revisão no âmbito estadual. Como estrutura geral, identifique instauração, instrução com participação do interessado, relatório quando previsto e decisão motivada. Legalidade, finalidade, motivação, razoabilidade, proporcionalidade, contraditório, segurança jurídica e eficiência orientam a tramitação. A autoridade competente deve decidir e explicitar fatos e fundamentos jurídicos.' },
    ],
    question: 'A decisão administrativa impõe sanção sem permitir ao interessado conhecer as provas do processo. Qual garantia foi violada?',
    answer: 'Contraditório e ampla defesa, assegurados pelo art. 5º, LV, da Constituição. O processo deve permitir ciência e reação efetiva antes da decisão, ressalvadas medidas cautelares motivadas previstas em lei.',
    sources: [{ title: 'Lei Estadual 7.692/2002 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }, { title: 'Lei 9.784/1999 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9784.htm' }],
  },
  'dir1-8': {
    sections: [
      { title: 'Lei 14.133/2021 e planejamento', text: 'A Lei 14.133/2021 estabelece normas gerais para licitações e contratos da Administração direta, autárquica e fundacional dos entes federativos. Princípios incluem planejamento, transparência, segregação de funções, motivação, julgamento objetivo, competitividade e desenvolvimento nacional sustentável. A fase preparatória identifica necessidade, estudo técnico preliminar quando cabível, termo de referência ou projeto, orçamento estimado, riscos, modalidade, critério e condições do edital.' },
      { title: 'Modalidades, julgamento e contratação direta', text: 'As modalidades são pregão, concorrência, concurso, leilão e diálogo competitivo. Convite e tomada de preços foram substituídos. Critérios incluem menor preço, maior desconto, melhor técnica ou conteúdo artístico, técnica e preço, maior lance e maior retorno econômico. Dispensa ocorre nas hipóteses legais em que a competição é possível, mas a lei autoriza contratar diretamente. Inexigibilidade decorre de inviabilidade de competição. Ambas exigem processo instruído, justificativa e publicidade legal.' },
      { title: 'Contratos, nulidade e controle', text: 'O contrato deve definir objeto, preço, prazos, responsabilidades, garantias, riscos e hipóteses de alteração e extinção. A Administração dispõe de prerrogativas legais, incluindo fiscalização, sanções e extinção unilateral nos casos previstos. Alterações devem respeitar fundamentos e limites legais. Irregularidade exige análise do interesse público, saneamento possível e consequências da nulidade, com motivação e contraditório quando cabível. Sanções incluem advertência, multa, impedimento e declaração de inidoneidade, observada defesa.' },
    ],
    question: 'Uma contratação sem disputa por fornecedor exclusivo é dispensa?',
    answer: 'Em tese, é inexigibilidade quando a competição é inviável, como na hipótese legal de fornecedor exclusivo. A exclusividade deve ser comprovada no processo e não pode ser presumida.',
    sources: [{ title: 'Lei 14.133/2021 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/L14133.htm' }],
  },
  'dir1-9': {
    sections: [
      { title: 'Regime e classificação', text: 'Bens públicos são bens pertencentes às pessoas jurídicas de direito público interno. Bens de uso comum do povo incluem ruas e rios públicos. Bens de uso especial são afetados a serviço ou estabelecimento público. Bens dominicais integram o patrimônio disponível, sem destinação pública específica. Os bens de uso comum e especial são inalienáveis enquanto mantiverem a qualificação, conforme Código Civil. Bens públicos não se sujeitam a usucapião.' },
      { title: 'Uso por particulares e alienação', text: 'O uso privativo pode decorrer de autorização, permissão ou concessão de uso, conforme lei, prazo, finalidade e intensidade. Autorização tende a ser unilateral e precária. Permissão formaliza uso consentido e pode ter caráter precário. Concessão é contrato e tende a conferir maior estabilidade nos termos pactuados. Alienação de imóvel público exige interesse público justificado, avaliação e autorização legislativa quando cabível, além de licitação, ressalvadas hipóteses legais. Desafetação retira a destinação pública específica quando exigida para alienar.' },
    ],
    question: 'Uma praça pública está afetada ao uso comum. Pode ser vendida imediatamente?',
    answer: 'Não. Bens de uso comum são inalienáveis enquanto conservarem essa qualificação. É preciso observar a desafetação e os requisitos legais de alienação.',
    sources: [{ title: 'Código Civil · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm' }, { title: 'Lei 14.133/2021 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/L14133.htm' }],
  },
  'dir1-10': {
    sections: [
      { title: 'Cargo, emprego, função e provimento', text: 'Cargo é unidade de atribuições criada por lei, ocupada por servidor sob regime estatutário. Emprego público é vínculo contratual, em geral celetista. Função pública descreve atribuições, inclusive função de confiança. Provimento originário ocorre por nomeação; formas derivadas e seus limites dependem da Constituição e do estatuto. Vacância decorre de exoneração, demissão, promoção, readaptação, aposentadoria, posse em cargo inacumulável ou falecimento, conforme regime aplicável.' },
      { title: 'Acumulação e direitos', text: 'A regra constitucional é vedar acumulação remunerada de cargos públicos, com exceções de dois cargos de professor, um de professor com outro técnico ou científico, e dois cargos ou empregos privativos de profissionais de saúde com profissões regulamentadas. Em todos os casos deve haver compatibilidade de horários e respeito ao teto. Direitos e vantagens dependem da Constituição e do estatuto do ente. Não se presume que o regime federal da Lei 8.112/1990 se aplique ao servidor estadual.' },
      { title: 'Estabilidade e disciplina', text: 'A estabilidade constitucional exige nomeação para cargo efetivo por concurso e três anos de efetivo exercício, além de avaliação especial. Servidor estável pode perder o cargo nas hipóteses do art. 41, com processo administrativo com ampla defesa, decisão judicial transitada em julgado ou avaliação periódica de desempenho conforme lei complementar. Estabilidade não é imunidade disciplinar nem se confunde com efetividade, estágio probatório ou estabilidade econômica.' },
    ],
    question: 'Servidor estadual acumula dois cargos de professor com compatibilidade de horários. A exceção constitucional pode alcançar o caso?',
    answer: 'Sim, a Constituição admite dois cargos de professor, desde que exista compatibilidade de horários e sejam observadas as demais regras constitucionais, como o teto remuneratório.',
    sources: [{ title: 'Constituição Federal · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }],
  },
  'dir1-11': {
    sections: [
      { title: 'Estrutura administrativa', text: 'Órgãos são centros de competência sem personalidade jurídica própria. A criação e distribuição de órgãos correspondem à desconcentração. Entidades têm personalidade própria e decorrem de descentralização. A administração direta atua por órgãos dos entes. A indireta inclui autarquias, fundações públicas, empresas públicas e sociedades de economia mista. Centralização ocorre quando o próprio ente executa a atividade. Descentralização por serviço cria ou autoriza entidade. Descentralização por colaboração delega execução a particular nos termos legais.' },
      { title: 'Controle e relações', text: 'Hierarquia existe dentro da mesma pessoa jurídica e permite ordens, revisão e disciplina, nos limites legais. Tutela administrativa controla entidade descentralizada segundo a lei, sem hierarquia. Controle interno ocorre dentro do Poder ou órgão. Controle externo, como o realizado pelo Legislativo com auxílio dos tribunais de contas, e controle judicial verificam legalidade e outros parâmetros constitucionais. A organização deve respeitar legalidade, finalidade e competência.' },
    ],
    question: 'Uma autarquia pode receber ordens hierárquicas diárias do ministério ao qual está vinculada?',
    answer: 'A vinculação não cria hierarquia. O ministério exerce supervisão nos limites legais e não substitui a autonomia administrativa da autarquia.',
    sources: [{ title: 'Decreto-Lei 200/1967 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del0200.htm' }],
  },
  'dir1-12': {
    sections: [
      { title: 'Improbidade administrativa', text: 'A Lei 8.429/1992, alterada pela Lei 14.230/2021, disciplina atos de improbidade. Exige conduta dolosa tipificada nos arts. 9º, 10 ou 11, conforme o caso. Enriquecimento ilícito envolve vantagem patrimonial indevida. Prejuízo ao erário exige perda patrimonial efetiva e dolosa. Violação a princípios demanda enquadramento legal e finalidade indevida nos termos da lei. A mera ilegalidade, divergência interpretativa ou exercício regular de função sem dolo não configuram automaticamente improbidade.' },
      { title: 'Sanções, processo e lei estadual', text: 'As sanções variam segundo o tipo, gravidade e critérios legais, e dependem de processo judicial com garantias de defesa. O Ministério Público tem legitimidade para a ação nos termos definidos pela lei e pela jurisprudência constitucional. A Lei Estadual 7.692/2002 regula o processo administrativo no Estado de Mato Grosso e disciplina atuação, direitos dos interessados, instrução, decisão, recursos e revisão. Ela não substitui o processo judicial de improbidade. Ao estudar o edital, compare o texto estadual atualizado com a lei federal.' },
    ],
    question: 'Uma falha formal sem dolo e sem enquadramento em tipo legal é suficiente, por si só, para condenação por improbidade?',
    answer: 'Não. A Lei 8.429, após a reforma, exige conduta dolosa tipificada. Responsabilidades administrativas ou civis podem ser examinadas por seus próprios fundamentos, mas não se confundem automaticamente com improbidade.',
    sources: [{ title: 'Lei 8.429/1992 atualizada · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l8429.htm' }, { title: 'Lei Estadual 7.692/2002 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }],
  },
  'dir2-1': {
    sections: [
      { title: 'Vigência, aplicação e irretroatividade', text: 'A lei começa a vigorar no país 45 dias depois de oficialmente publicada, salvo disposição contrária. Nos Estados estrangeiros, quando admitida, a obrigatoriedade inicia três meses após a publicação oficial. A vacatio legis permite conhecimento e adaptação. Salvo disposição em contrário, a lei tem vigor até que outra a modifique ou revogue. A lei nova tem efeito imediato e geral, respeitados ato jurídico perfeito, direito adquirido e coisa julgada. O princípio da irretroatividade protege essas situações, embora a lei possa alcançar efeitos futuros de relações em curso dentro dos limites constitucionais.' },
      { title: 'Revogação e repristinação', text: 'Revogação expressa declara a retirada da lei anterior. Tácita ocorre quando a nova lei é incompatível com a anterior ou regula inteiramente a matéria. Ab-rogação retira a lei inteira. Derrogação retira parte dela. A lei revogada não volta automaticamente a vigorar quando a lei revogadora perde efeito, salvo disposição expressa em contrário, conforme art. 2º, §3º, da LINDB.' },
    ],
    question: 'Lei nova revoga a lei que havia revogado outra anterior. A primeira lei volta automaticamente?',
    answer: 'Não. A repristinação não ocorre automaticamente no Brasil. Só se restaura a lei anterior se a nova lei revogadora expressamente dispuser nesse sentido.',
    sources: [{ title: 'LINDB · Decreto-Lei 4.657/1942', url: 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del4657compilado.htm' }],
  },
  'dir2-2': {
    sections: [
      { title: 'Pessoa natural', text: 'A personalidade civil começa com o nascimento com vida, mas a lei põe a salvo, desde a concepção, direitos do nascituro. Capacidade de direito é a aptidão para titularizar direitos. Capacidade de exercício é a possibilidade de exercê-los pessoalmente e pode sofrer limitações legais. Menores de 16 anos são absolutamente incapazes de exercer pessoalmente atos da vida civil. Entre 16 e 18 anos, são relativamente incapazes, salvo emancipação. Ausência, morte presumida, domicílio, nome e estado da pessoa também integram o estudo da personalidade.' },
      { title: 'Pessoas jurídicas', text: 'Pessoas jurídicas de direito público interno incluem União, Estados, Distrito Federal, Municípios, autarquias e outras entidades previstas em lei. Pessoas jurídicas de direito público externo incluem Estados estrangeiros e organismos regidos pelo direito internacional público. Pessoas privadas incluem associações, sociedades, fundações privadas, organizações religiosas, partidos políticos e outras figuras do Código Civil. A personalidade da pessoa jurídica privada começa com o registro do ato constitutivo, quando exigido.' },
      { title: 'Modificações e direitos da personalidade', text: 'Emancipação pode decorrer de concessão dos pais por instrumento público, casamento, exercício de emprego público efetivo, colação de grau ou economia própria nas hipóteses legais. Direitos da personalidade protegem nome, imagem, honra, intimidade e integridade. São intransmissíveis e irrenunciáveis nos limites legais, e a ameaça ou lesão pode justificar tutela inibitória e reparação.' },
    ],
    question: 'A pessoa jurídica pode sofrer dano moral?',
    answer: 'Sim, conforme a Súmula 227 do STJ. A proteção se relaciona à honra objetiva, como reputação e credibilidade perante terceiros.',
    sources: [{ title: 'Código Civil · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm' }],
  },
  'dir2-3': {
    sections: [
      { title: 'Fato, ato e negócio jurídico', text: 'Fato jurídico em sentido amplo é acontecimento que produz efeitos reconhecidos pelo direito. Ato jurídico em sentido estrito envolve manifestação de vontade com efeitos previstos em lei. Negócio jurídico permite que a vontade configure efeitos dentro dos limites jurídicos. Para validade, exigem-se agente capaz, objeto lícito, possível e determinado ou determinável, e forma prescrita ou não proibida em lei. A prova pode decorrer de documentos, confissão, testemunhas, presunções e perícia conforme regras aplicáveis.' },
      { title: 'Defeitos e invalidade', text: 'Erro substancial, dolo, coação, estado de perigo, lesão e fraude contra credores podem tornar o negócio anulável, conforme requisitos legais. Simulação gera nulidade. Nulidade também pode decorrer de objeto ilícito ou forma essencial desrespeitada. A anulabilidade pode ser confirmada nos casos legais e depende de provocação de quem tem legitimidade. Nulidade absoluta não se confirma pelo tempo, embora pretensões patrimoniais relacionadas possam prescrever.' },
      { title: 'Boa-fé e ato ilícito', text: 'Boa-fé subjetiva é estado de consciência sobre a própria conduta ou situação. Boa-fé objetiva é padrão de lealdade, cooperação e confiança, que cria deveres anexos antes, durante e depois do contrato. Abuso de direito ocorre quando o titular excede manifestamente limites impostos por finalidade econômica ou social, boa-fé ou bons costumes. Ato ilícito pode gerar obrigação de reparar o dano.' },
    ],
    question: 'As partes simulam contrato para ocultar doação proibida. O negócio é apenas anulável por erro?',
    answer: 'A simulação é causa de nulidade do negócio jurídico pelo art. 167 do Código Civil. Devem ser examinados os efeitos do negócio dissimulado se válido na substância e na forma.',
    sources: [{ title: 'Código Civil · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm' }],
  },
  'dir2-4': {
    sections: [
      { title: 'Prescrição', text: 'Prescrição atinge a pretensão de exigir judicialmente uma prestação após violação do direito e decurso do prazo legal. A regra geral do Código Civil é de dez anos quando a lei não estabelecer prazo menor. Há prazos específicos, como três anos para reparação civil e cinco anos para cobrança de dívida líquida constante de instrumento público ou particular. A prescrição pode ser impedida, suspensa ou interrompida apenas nas hipóteses legais. Interrupção só pode ocorrer uma vez e reinicia a contagem conforme a causa.' },
      { title: 'Decadência', text: 'Decadência extingue o próprio direito potestativo pelo decurso do prazo. Pode ser legal ou convencional. A decadência legal não pode ser renunciada e deve ser reconhecida de ofício nos casos previstos. A convencional pode ser alegada pela parte beneficiada. Em regra, não se aplicam à decadência as causas de impedimento, suspensão e interrupção da prescrição, salvo previsão legal.' },
    ],
    question: 'Uma lei fixa prazo para exercer direito potestativo de anular negócio por lesão. Em regra, trata-se de prescrição ou decadência?',
    answer: 'Em regra, decadência, pois o prazo atinge direito potestativo de anular. É necessário verificar o dispositivo legal específico e o termo inicial.',
    sources: [{ title: 'Código Civil · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm' }],
  },
  'dir2-5': {
    sections: [
      { title: 'Classificações dos bens', text: 'Bens imóveis incluem o solo e o que a ele se incorpora natural ou artificialmente, além dos direitos legalmente equiparados. Móveis podem ser transportados sem alteração substancial ou são legalmente considerados móveis, como energias com valor econômico. Fungíveis podem ser substituídos por outros da mesma espécie, qualidade e quantidade. Consumíveis se destroem com o uso ou se destinam à alienação. Divisíveis podem ser fracionados sem alteração substancial de valor ou prejuízo. Bens singulares são considerados individualmente e coletivos formam universalidade.' },
      { title: 'Bens reciprocamente considerados', text: 'Principal existe sobre si. Acessório supõe o principal. Frutos e produtos, pertenças, benfeitorias e partes integrantes têm consequências distintas. Pertenças servem duradouramente ao uso, serviço ou aformoseamento de outro bem, sem constituir parte integrante. Benfeitorias podem ser necessárias, úteis ou voluptuárias. A classificação orienta transferência, garantia, posse e indenização.' },
      { title: 'Bens públicos', text: 'Bens públicos pertencem a pessoas jurídicas de direito público interno. São de uso comum, de uso especial ou dominicais. Os dois primeiros são inalienáveis enquanto conservarem a qualificação e todos os bens públicos são insuscetíveis de usucapião. O regime constitucional também protege bens públicos contra penhora ordinária, observadas as formas constitucionais de pagamento.' },
    ],
    question: 'Um equipamento removível, instalado para atender uma atividade em um imóvel, sempre se torna parte integrante do imóvel?',
    answer: 'Não necessariamente. Pode ser pertença se conservar individualidade e servir duradouramente ao uso ou serviço do imóvel. A classificação depende de destinação e integração concreta.',
    sources: [{ title: 'Código Civil · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm' }],
  },
  'dir2-6': {
    sections: [
      { title: 'Modalidades e transmissão', text: 'Obrigações podem ser de dar coisa certa ou incerta, fazer ou não fazer. Nas divisíveis e indivisíveis, examine objeto e pluralidade de sujeitos. Solidariedade não se presume e resulta da lei ou vontade das partes. Cessão de crédito transfere o crédito, observadas as regras de eficácia perante devedor e terceiros. Assunção de dívida requer consentimento expresso do credor, ressalvadas hipóteses legais. Sub-rogação transfere direitos do credor que recebeu pagamento por terceiro ou por interessado.' },
      { title: 'Adimplemento e extinção', text: 'Pagamento deve ser feito ao credor ou representante legítimo, no tempo, lugar e forma devidos. Consignação em pagamento pode liberar o devedor diante das hipóteses legais. Novação cria obrigação nova para extinguir e substituir a anterior, com intenção inequívoca. Compensação extingue obrigações recíprocas até onde se equivalem quando presentes requisitos. Remissão, confusão e dação em pagamento também podem extinguir obrigação.' },
      { title: 'Inadimplemento e cláusula penal', text: 'O inadimplemento pode gerar perdas e danos, juros, atualização monetária e honorários conforme a lei e o contrato. Mora é atraso imputável no cumprimento, observados termo e constituição em mora. Cláusula penal pode ser compensatória ou moratória e não exceder o valor da obrigação principal. O juiz deve reduzi-la equitativamente em caso de cumprimento parcial ou excesso manifesto, conforme art. 413.' },
    ],
    question: 'A solidariedade entre devedores existe automaticamente sempre que a obrigação é indivisível?',
    answer: 'Não. Indivisibilidade decorre do objeto não fracionável. Solidariedade decorre da lei ou vontade das partes. As duas figuras podem coexistir, mas não se confundem.',
    sources: [{ title: 'Código Civil · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm' }],
  },
  'dir2-7': {
    sections: [
      { title: 'Formação e princípios contratuais', text: 'O contrato depende de capacidade, objeto lícito e forma adequada, além do acordo de vontades. A liberdade contratual é exercida nos limites da função social. As partes devem observar probidade e boa-fé na conclusão e execução. A proposta vincula o proponente nos termos legais, e aceitação tardia ou modificada pode constituir nova proposta. Contratos podem ser paritários, de adesão, gratuitos, onerosos, comutativos ou aleatórios.' },
      { title: 'Espécies previstas no edital', text: 'Compra e venda transfere obrigação de entregar coisa mediante preço. Doação transfere bens por liberalidade e pode conter encargo. Comodato empresta gratuitamente coisa infungível; mútuo transfere coisa fungível com obrigação de restituir equivalente. Prestação de serviço rege trabalho não sujeito a disciplina trabalhista específica. Empreitada objetiva obra ou resultado. Locação cede uso e gozo por remuneração. Depósito guarda coisa móvel. Mandato autoriza atuação em nome alheio. Transação previne ou encerra litígio mediante concessões mútuas.' },
      { title: 'Extinção contratual', text: 'O contrato se extingue pelo cumprimento, distrato, resilição unilateral quando permitida, resolução por inadimplemento ou onerosidade excessiva nas condições legais, e outras causas próprias. Arras podem confirmar o contrato ou permitir arrependimento se pactuadas. Na extinção, analise cláusulas, boa-fé, investimentos relevantes e efeitos perante terceiros.' },
    ],
    question: 'No comodato, o comodatário recebe dinheiro fungível e devolve a mesma quantidade, espécie e qualidade?',
    answer: 'Não. Isso descreve mútuo. Comodato é empréstimo gratuito de coisa infungível, com devolução da própria coisa.',
    sources: [{ title: 'Código Civil · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm' }],
  },
  'dir2-8': {
    sections: [
      { title: 'Registros públicos', text: 'A Lei 6.015/1973 organiza registros públicos para autenticidade, segurança, publicidade e eficácia de atos jurídicos. O registro civil das pessoas naturais documenta nascimento, casamento, óbito e outros atos. O registro civil de pessoas jurídicas inscreve atos constitutivos de entidades e sociedades simples conforme competência. O registro de títulos e documentos conserva e publiciza atos e documentos nos casos legais. O registro de imóveis acompanha titularidade, direitos reais, ônus e atos sujeitos a registro ou averbação.' },
      { title: 'Fundações', text: 'Fundação privada resulta da afetação de patrimônio a finalidade não econômica definida pelo instituidor, por escritura pública ou testamento. O Código Civil prevê finalidades admitidas e atuação do Ministério Público na fiscalização. Fundação pública integra a Administração indireta quando instituída pelo poder público, com personalidade e regime definidos na lei autorizadora e no ato de criação. Não se deve confundir fundação pública de direito privado com fundação privada apenas porque ambas adotem forma de direito privado.' },
    ],
    question: 'O registro de imóveis tem função apenas informativa, sem efeitos sobre publicidade ou oponibilidade de direitos?',
    answer: 'Não. O registro dá publicidade e, nos casos legais, constitui ou torna oponíveis direitos reais e atos relacionados ao imóvel.',
    sources: [{ title: 'Lei 6.015/1973 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l6015compilada.htm' }, { title: 'Código Civil · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm' }],
  },
  'dir3-1': {
    sections: [
      { title: 'Norma processual no tempo e no espaço', text: 'O processo civil é regido pelas normas processuais brasileiras em todo o território nacional, ressalvadas disposições específicas de tratados e convenções. A lei processual tem aplicação imediata aos processos em curso, respeitados os atos processuais já praticados e as situações consolidadas sob a lei revogada. Cada ato segue, em regra, a lei vigente no momento em que é praticado, conforme o isolamento dos atos processuais. O CPC entrou em vigor em 2016 e não invalida atos regularmente realizados sob o código anterior.' },
      { title: 'Princípios do processo civil', text: 'A Constituição assegura acesso à justiça, devido processo legal, contraditório, ampla defesa, juiz natural, publicidade e duração razoável. O CPC acrescenta cooperação, boa-fé, paridade de tratamento, solução integral do mérito e proporcionalidade. O contraditório inclui ciência e possibilidade real de influência. Em regra, o juiz não pode decidir contra uma parte com fundamento sobre o qual ela não teve oportunidade de se manifestar, mesmo em matéria cognoscível de ofício, ressalvadas hipóteses legais.' },
      { title: 'Dispositivo, impulso e fundamentação', text: 'A iniciativa da parte é necessária para iniciar a jurisdição, mas o processo se desenvolve por impulso oficial depois de instaurado. O juiz deve decidir nos limites do pedido e fundamentar decisões enfrentando argumentos capazes de alterar a conclusão. A cooperação orienta juiz e partes a construir decisão de mérito justa e efetiva, sem eliminar ônus processuais ou imparcialidade.' },
    ],
    question: 'Em processo iniciado antes de uma nova lei processual, um ato ainda não praticado deve seguir qual lei?',
    answer: 'Em regra, aplica-se imediatamente a lei nova ao ato futuro, preservando atos já praticados e situações consolidadas. É o isolamento dos atos processuais.',
    sources: [{ title: 'CPC, arts. 1º a 15 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }],
  },
  'dir3-2': {
    sections: [
      { title: 'Jurisdição, ação e competência', text: 'Jurisdição é a atividade estatal de resolver conflitos e tutelar direitos com autoridade. A ação é o direito de provocar a jurisdição e obter resposta, condicionado aos requisitos processuais e examinado à luz da primazia do mérito. A classificação pode considerar natureza do provimento, como declaratória, constitutiva ou condenatória, e tipo de tutela. Limites da jurisdição nacional estão nos arts. 21 a 25 do CPC. Cooperação jurídica internacional permite citação, produção de prova e reconhecimento de decisões, respeitados soberania e ordem pública.' },
      { title: 'Equivalentes e métodos adequados', text: 'Conciliação favorece aproximação e pode sugerir opções, sobretudo quando não há vínculo anterior. Mediação facilita comunicação e construção de solução pelas próprias partes, especialmente em relações continuadas. Negociação ocorre diretamente entre interessados ou representantes. Arbitragem é jurisdição privada fundada em convenção arbitral para direitos patrimoniais disponíveis. A Administração pode arbitrar conflitos patrimoniais disponíveis nos termos da Lei 9.307/1996, com autoridade competente para firmar convenção.' },
      { title: 'Organização do Judiciário', text: 'O Judiciário é organizado por órgãos federais e estaduais previstos na Constituição. O CPC disciplina a atividade jurisdicional civil e se articula com legislação de organização judiciária. O juiz natural exige competência definida previamente e veda tribunal de exceção. Métodos consensuais podem ser estimulados durante o processo sem afastar o acesso à justiça.' },
    ],
    question: 'Uma autarquia celebra cláusula compromissória para controvérsia patrimonial disponível. A arbitragem é sempre proibida à Administração?',
    answer: 'Não. A Lei de Arbitragem admite arbitragem pela Administração Pública para conflitos relativos a direitos patrimoniais disponíveis, observada a competência para celebrar a convenção e as exigências legais.',
    sources: [{ title: 'CPC · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }, { title: 'Lei de Arbitragem · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9307.htm' }],
  },  'dir3-3': { sections: [{ title: 'Critérios e espécies de competência', text: 'A competência distribui a jurisdição por matéria, pessoa, função, território e valor. Competência absoluta decorre sobretudo de matéria, pessoa ou função e não pode ser modificada por convenção. A relativa, em regra territorial ou de valor, pode prorrogar-se se o réu não alegar em preliminar de contestação. A incompetência deve ser alegada no momento processual adequado, e o juiz pode reconhecer de ofício a absoluta. A competência federal está no art. 109 da Constituição. A presença da União, autarquia ou empresa pública federal pode atrair a Justiça Federal, com exceções constitucionais, e sociedade de economia mista federal não a atrai automaticamente.' }, { title: 'Modificação e cooperação', text: 'Conexão ocorre quando ações compartilham pedido ou causa de pedir. Continência exige mesmas partes e causa de pedir, com pedido de uma ação abrangendo o da outra. Reunião evita decisões contraditórias quando possível. Juízos cooperam por auxílio direto, reunião ou apensamento, prestação de informações e atos concertados. Na competência internacional, arts. 21 a 25 do CPC distinguem jurisdição concorrente e exclusiva brasileira. A cláusula estrangeira exclusiva pode afastar jurisdição concorrente se arguida pelo réu e válida.' }], question: 'O réu deixa de alegar incompetência territorial na contestação. Qual é a consequência usual?', answer: 'Prorroga-se a competência relativa. A incompetência absoluta, em contraste, pode ser reconhecida de ofício e não se prorroga.', sources: [{ title: 'CPC e Constituição · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }] },
  'dir3-4': { sections: [{ title: 'Partes, representação e litisconsórcio', text: 'Parte é quem pede tutela jurisdicional e contra quem ela é pedida, além de intervenientes admitidos. Capacidade de ser parte, capacidade processual e capacidade postulatória são distintas. Pessoa incapaz é representada ou assistida conforme a lei. Advogado atua com procuração, ressalvadas exceções. Litisconsórcio reúne mais de duas partes no mesmo polo e pode ser necessário ou facultativo, unitário ou simples. No unitário, a decisão deve ser uniforme para os litisconsortes.' }, { title: 'Intervenções e auxiliares', text: 'Assistência permite terceiro juridicamente interessado apoiar uma parte. Denunciação da lide e chamamento ao processo promovem participação de terceiros nas hipóteses legais. Incidente de desconsideração alcança patrimônio de sócio ou pessoa jurídica com contraditório. Amicus curiae contribui em causa relevante sem se tornar parte comum. Juiz deve ser imparcial e pode ser impedido ou suspeito. Auxiliares incluem escrivão, oficial de justiça, perito, depositário e intérprete. Ministério Público, Advocacia Pública e Defensoria atuam segundo funções constitucionais e processuais próprias.' }], question: 'No litisconsórcio unitário, a decisão pode ser diferente para cada litisconsorte no mesmo polo?', answer: 'Em regra, não. A relação jurídica exige decisão uniforme, sem prejuízo de atos ou defesas pessoais que produzam efeitos próprios.', sources: [{ title: 'CPC · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }] },
  'dir3-5': { sections: [{ title: 'Forma, tempo e comunicação', text: 'Atos processuais independem de forma determinada salvo exigência legal, devem ser públicos, salvo segredo, e podem ocorrer eletronicamente. Prazos processuais em dias são contados em dias úteis quando fixados em dias, excluindo o dia do começo e incluindo o vencimento. Citação convoca réu, executado ou interessado para integrar a relação processual. Intimação dá ciência dos atos e termos do processo. A comunicação pode ser eletrônica, postal, por oficial ou edital, conforme os requisitos legais.' }, { title: 'Nulidades, distribuição e registro', text: 'Nulidade exige exame da forma legal, prejuízo e finalidade do ato. Deve-se preservar o que puder ser aproveitado. A distribuição torna aleatória e equitativa a designação do juízo, observada prevenção. Registro documenta a demanda. A falta ou nulidade da citação pode comprometer a validade do processo, mas comparecimento espontâneo supre o vício e inicia prazo de defesa.' }], question: 'A parte comparece espontaneamente apesar de não citada. O processo necessariamente deve ser extinto?', answer: 'Não. O comparecimento espontâneo supre a falta ou nulidade da citação, e o prazo de contestação começa dessa data, conforme o CPC.', sources: [{ title: 'CPC · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }] },
  'dir3-6': { sections: [{ title: 'Urgência e evidência', text: 'Tutela provisória pode fundar-se em urgência ou evidência. Urgência exige probabilidade do direito e perigo de dano ou risco ao resultado útil. Pode ser cautelar, para assegurar resultado, ou antecipada, para adiantar efeitos. Pode ser antecedente ou incidental. Tutela antecipada não deve ser concedida quando houver perigo de irreversibilidade dos efeitos. Tutela de evidência dispensa perigo e cabe nas situações do art. 311, como abuso de defesa ou prova documental associada a tese firmada em precedentes qualificados.' }, { title: 'Procedimento e estabilização', text: 'Tutela de urgência pode ser concedida liminarmente ou após justificação. A tutela cautelar antecedente tem procedimento próprio. A antecipada antecedente pode estabilizar-se se concedida e o réu não interpuser o recurso cabível, extinguindo-se o processo, sem coisa julgada material e com possibilidade de ação para rever, reformar ou invalidar nos prazos legais.' }], question: 'Tutela de evidência exige demonstração de perigo de dano?', answer: 'Não. A evidência dispensa perigo, desde que se enquadre em uma das hipóteses taxativas do art. 311 do CPC.', sources: [{ title: 'CPC · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }] },  'dir3-7': { sections: [{ title: 'Formação, suspensão e extinção', text: 'O processo começa por iniciativa da parte e se desenvolve por impulso oficial. Forma-se com o protocolo da petição inicial, mas a relação processual se completa com a citação válida. Suspende-se nas hipóteses do art. 313, como morte, convenção das partes, incidente de resolução de demandas repetitivas e força maior. Durante a suspensão, atos urgentes podem ser praticados para evitar dano irreparável. A extinção pode ocorrer com resolução do mérito, como no acolhimento do pedido, ou sem resolução, como por abandono após os requisitos legais.' }, { title: 'Calendário e negócios processuais', text: 'O juiz pode adaptar o procedimento às necessidades da causa, respeitando contraditório e garantias fundamentais. As partes plenamente capazes podem convencionar mudanças procedimentais e distribuir ônus, poderes e faculdades antes ou durante o processo, desde que o direito permita autocomposição e não haja nulidade abusiva ou vulnerabilidade. O juiz controla a validade do negócio processual.' }], question: 'As partes convencionam suspender o processo por prazo indeterminado. O juiz deve aceitar?', answer: 'Não. O CPC permite suspensão convencional por prazo determinado, limitado a seis meses. O juiz controla validade e limites legais.', sources: [{ title: 'CPC · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }] },
  'dir3-8': { sections: [{ title: 'Petição inicial e resposta', text: 'O procedimento comum começa com petição que identifica juízo, partes, fatos, fundamentos, pedido certo e determinado, valor da causa, provas e opção sobre audiência consensual. Defeitos sanáveis devem ser objeto de oportunidade de emenda. Improcedência liminar pode ocorrer nas hipóteses do art. 332, sem citação, quando o pedido contrariar precedente qualificado ou prescrição e decadência forem verificáveis. A contestação concentra defesas processuais e de mérito. Reconvenção formula pretensão própria conexa. Revelia não significa vitória automática, pois seus efeitos materiais têm exceções.' }, { title: 'Saneamento, prova e julgamento', text: 'Após respostas e providências preliminares, o juiz pode julgar antecipadamente o mérito se não houver necessidade de outras provas, total ou parcialmente. Caso contrário, saneia, delimita questões e organiza a instrução. A audiência de instrução colhe depoimentos e prova oral. O ônus da prova incumbe ao autor quanto ao fato constitutivo e ao réu quanto a fato impeditivo, modificativo ou extintivo, com distribuição dinâmica fundamentada quando cabível.' }, { title: 'Sentença e coisa julgada', text: 'Sentença encerra fase cognitiva ou execução. Deve conter relatório quando exigido, fundamentos e dispositivo. Coisa julgada material torna imutável e indiscutível decisão de mérito não mais sujeita a recurso, nos limites objetivos e subjetivos legais. Motivos e verdade dos fatos não fazem coisa julgada por si, ressalvadas hipóteses legais.' }], question: 'O réu é revel em ação que trata de direito indisponível. O juiz deve presumir verdadeiros todos os fatos?', answer: 'Não. A presunção material da revelia não se aplica, entre outras exceções, quando o litígio versa sobre direitos indisponíveis.', sources: [{ title: 'CPC · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }] },
  'dir3-9': { sections: [{ title: 'Cumprimento provisório e definitivo', text: 'Cumprimento de sentença executa título judicial perante o juízo competente. Em obrigação de pagar quantia, o devedor é intimado para pagar em quinze dias, sob multa e honorários do art. 523 se não pagar voluntariamente. No provisório, cabe execução enquanto houver recurso sem efeito suspensivo, com regras de responsabilidade e caução para levantamento em certos casos. Obrigações de fazer, não fazer e entregar coisa admitem medidas específicas para obter resultado prático equivalente.' }, { title: 'Fazenda Pública e impugnação', text: 'A Fazenda Pública é intimada para impugnar em trinta dias, nos próprios autos, e paga por precatório ou requisição de pequeno valor conforme Constituição. Não incide a multa do art. 523. A impugnação pode alegar matérias do art. 525, como inexigibilidade do título, excesso e ilegitimidade. Decisão do STF sobre inconstitucionalidade pode afetar exigibilidade nos termos do CPC e da modulação aplicável.' }], question: 'O ente público não impugna cumprimento de sentença de pagar quantia. O pagamento ocorre por bloqueio imediato de conta?', answer: 'Em regra, não. O pagamento da Fazenda segue regime constitucional de precatório ou RPV, conforme o valor e o ente devedor.', sources: [{ title: 'CPC · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }, { title: 'Constituição, art. 100 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }] },  'dir3-10': { sections: [{ title: 'Procedimentos especiais do CPC', text: 'Consignação em pagamento permite liberar o devedor quando o credor recusa ou há dúvida sobre quem deve receber, observados depósito e hipóteses legais. Ação de exigir contas apura administração de bens ou interesses alheios. Ações possessórias protegem posse por manutenção, reintegração ou interdito proibitório. Divisão e demarcação definem limites e repartem imóvel comum. Embargos de terceiro protegem posse ou propriedade de quem sofre constrição sem ser parte. A monitória exige prova escrita sem eficácia executiva e permite formar título judicial se não houver pagamento nem embargos.' }, { title: 'Jurisdição voluntária e leis especiais', text: 'Jurisdição voluntária inclui procedimentos em que o Judiciário integra ou fiscaliza interesses, como alienação judicial, notificação, interpelação, restauração de autos e homologação de penhor legal, conforme lei. Oposição e habilitação também seguem regras próprias do CPC. Mandado de segurança, habeas data e mandado de injunção são regidos por leis específicas. Suspensão de liminar protege interesse público nos casos legais. Alienação fiduciária de móveis e imóveis possui procedimentos próprios, inclusive busca e apreensão e consolidação da propriedade.' }], question: 'Terceiro que não integra a ação sofre penhora de bem que possui. Qual instrumento processual pode proteger sua posse?', answer: 'Embargos de terceiro, desde que demonstre posse ou direito incompatível com a constrição e atenda aos requisitos legais.', sources: [{ title: 'CPC · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }, { title: 'Lei 12.016/2009 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2009/lei/l12016.htm' }] },
  'dir3-11': { sections: [{ title: 'Execução e espécies', text: 'Execução realiza concretamente obrigação constante de título executivo. O credor deve apresentar título certo, líquido e exigível. Execução para entrega de coisa, fazer ou não fazer emprega técnicas específicas e pode converter-se em perdas e danos nas hipóteses legais. Execução por quantia começa com citação para pagar em três dias, sob pena de penhora. A desconsideração da personalidade jurídica segue incidente com contraditório, salvo hipóteses legais de pedido inicial.' }, { title: 'Fazenda, fiscal e defesa', text: 'Execução contra Fazenda Pública baseada em título extrajudicial também observa regime constitucional de pagamento. Execução fiscal é regida principalmente pela Lei 6.830/1980 e cobra dívida ativa, com citação, garantia e embargos. Embargos à execução independem de penhora para ajuizamento, mas a atribuição de efeito suspensivo depende de requisitos legais. Exceção de pré-executividade permite alegar matéria cognoscível de ofício e demonstrável sem dilação probatória.' }, { title: 'Extinção e prescrição intercorrente', text: 'A execução se extingue nas hipóteses do art. 924 do CPC, como satisfação da obrigação ou prescrição intercorrente. Na execução fiscal, a Lei 6.830 e o entendimento do STJ disciplinam suspensão e contagem da prescrição intercorrente após ausência de bens ou devedor localizável. A suspensão não deve ser confundida com extinção automática e a parte deve ser ouvida conforme o regime aplicável.' }], question: 'A parte alega nulidade evidente da execução demonstrável pelos próprios documentos, sem necessidade de prova. Pode usar exceção de pré-executividade?', answer: 'Pode, em tese, para matéria cognoscível de ofício e que não demande dilação probatória. A adequação depende da natureza concreta da alegação.', sources: [{ title: 'CPC · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }, { title: 'Lei de Execução Fiscal · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l6830.htm' }] },
  'dir3-12': { sections: [{ title: 'Precedentes e incidentes', text: 'O CPC exige coerência, integridade e estabilidade jurisprudencial. Juízes e tribunais observam decisões vinculantes indicadas no art. 927. IAC pode uniformizar questão relevante sem repetição em múltiplos processos. IRDR resolve questão comum de direito com risco à isonomia e segurança jurídica, suspendendo processos conforme decisão. Incidente de inconstitucionalidade reserva a declaração ao plenário ou órgão especial. Conflito de competência é resolvido pelo tribunal competente.' }, { title: 'Ação rescisória e reclamação', text: 'Ação rescisória desconstitui decisão de mérito transitada em julgado apenas nas hipóteses taxativas do art. 966, dentro do prazo decadencial de dois anos. Reclamação preserva competência do tribunal e autoridade de suas decisões e, conforme CPC, garante observância de súmula vinculante e precedentes qualificados. Decisão estrangeira pode ser homologada pelo STJ. Carta rogatória depende de exequatur do STJ, sem reexame do mérito estrangeiro.' }], question: 'Ação rescisória serve para corrigir qualquer decisão injusta após o trânsito em julgado?', answer: 'Não. Só cabe nas hipóteses legais taxativas e dentro do prazo. Não funciona como recurso geral nem permite simples reexame da justiça do resultado.', sources: [{ title: 'CPC · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }, { title: 'Constituição, art. 105 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }] },
  'dir3-13': { sections: [{ title: 'Regras gerais e recursos ordinários', text: 'Recurso exige cabimento, legitimidade, interesse, tempestividade, preparo quando devido e regularidade formal. Em regra, prazo é de quinze dias úteis, salvo embargos de declaração, de cinco dias. Apelação impugna sentença e pode ter efeitos devolutivo e suspensivo, com exceções. Agravo de instrumento cabe contra decisões interlocutórias nas hipóteses do art. 1.015 e em situações de urgência reconhecidas pelo STJ. Agravo interno leva decisão monocrática ao colegiado. Embargos de declaração corrigem omissão, contradição, obscuridade ou erro material.' }, { title: 'Tribunais superiores', text: 'Recurso ordinário tem hipóteses constitucionais específicas. Recurso especial ao STJ discute interpretação de lei federal e divergência, sem reexaminar fatos em regra. Recurso extraordinário ao STF discute questão constitucional com repercussão geral. Agravo pode destrancar recursos inadmitidos, conforme cabimento. Julgamento repetitivo e repercussão geral selecionam controvérsias e orientam casos semelhantes. Embargos de divergência uniformizam divergência interna nos tribunais superiores.' }], question: 'Parte usa embargos de declaração apenas para rediscutir prova e mudar a conclusão, sem apontar vício. Qual o problema?', answer: 'Embargos têm fundamentação vinculada a omissão, contradição, obscuridade ou erro material. Não servem para simples reexame do mérito, embora possam produzir efeito modificativo quando a correção do vício o exigir.', sources: [{ title: 'CPC · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }] },
  'dir3-14': { sections: [{ title: 'Juizados Especiais Federais', text: 'A Lei 10.259/2001 institui Juizados Especiais Cíveis e Criminais na Justiça Federal. No cível, a competência alcança causas até sessenta salários mínimos contra União, autarquias, fundações e empresas públicas federais, ressalvadas matérias excluídas, como mandado de segurança, desapropriação e ações coletivas. Onde instalado Juizado, a competência é absoluta dentro de sua alçada. Busca simplicidade, oralidade, economia, celeridade e conciliação.' }, { title: 'Procedimento, partes e recursos', text: 'Pessoas físicas, microempresas e empresas de pequeno porte podem propor ações nos termos da lei. Entidades federais demandadas apresentam documentação e proposta quando cabível. A sentença não condena a Fazenda a pagar quantia ilíquida. Há recurso para Turma Recursal, pedido de uniformização em questões de direito material nas hipóteses legais e recurso extraordinário quando cabível. O cumprimento observa RPV ou precatório conforme o valor e as regras constitucionais.' }], question: 'Causa contra autarquia federal no valor de 50 salários mínimos pode tramitar no JEF?', answer: 'Em princípio, sim, se não incidir matéria excluída e estiverem presentes os demais requisitos de competência e legitimidade da Lei 10.259/2001.', sources: [{ title: 'Lei 10.259/2001 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/leis_2001/l10259.htm' }] },  'dir3-15': { sections: [{ title: 'Tutela coletiva e legitimidade', text: 'Ações coletivas protegem direitos difusos, coletivos em sentido estrito e individuais homogêneos. A Lei 7.347/1985 disciplina ação civil pública e a Lei 8.078/1990 completa o microssistema coletivo. Ministério Público, Defensoria, entes federativos, órgãos públicos e associações podem ter legitimidade conforme requisitos legais. Inquérito civil é procedimento investigatório extrajudicial presidido pelo Ministério Público, que pode colher elementos e propor TAC, mas não é requisito obrigatório para ação.' }, { title: 'Competência, coisa julgada e acordos', text: 'Competência considera extensão do dano e regras do microssistema. Coisa julgada coletiva pode variar conforme natureza do direito e resultado, preservadas ações individuais nos termos legais. Execução pode ser coletiva ou individual, conforme titularidade e condenação. Termo de ajustamento de conduta é compromisso com eficácia de título executivo extrajudicial. Recomendações ministeriais orientam adequação da conduta, sem equivaler a sentença ou sanção automática. Conciliação deve observar disponibilidade e proteção adequada do direito coletivo.' }], question: 'A instauração de inquérito civil é condição obrigatória para o Ministério Público ajuizar ação civil pública?', answer: 'Não. O inquérito civil é instrumento facultativo de investigação. Havendo elementos suficientes, o Ministério Público pode ajuizar diretamente a ação.', sources: [{ title: 'Lei da Ação Civil Pública · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l7347orig.htm' }, { title: 'Código de Defesa do Consumidor · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm' }] },
  'dir3-16': { sections: [{ title: 'Aplicação temporal do CPC', text: 'O art. 14 do CPC determina aplicação imediata da norma processual aos processos em curso, sem retroagir para invalidar atos já praticados ou situações consolidadas sob a lei anterior. Adota-se o isolamento dos atos processuais: cada ato é regido pela lei vigente no momento em que ocorre. A regra combina efetividade da lei nova com segurança jurídica e proteção do ato jurídico perfeito.' }, { title: 'Processos pendentes e transição', text: 'Em processo iniciado sob o CPC anterior, atos futuros seguem o código vigente, observadas regras transitórias expressas. Prazos iniciados, recursos cabíveis e requisitos de atos podem depender da data de publicação da decisão e de dispositivos de transição. Não se deve aplicar automaticamente regra nova a prazo já iniciado nem reabrir ato precluso. O exame de questão exige identificar quando o ato foi praticado e eventual norma transitória específica.' }], question: 'Uma nova regra processual altera forma de intimação. Ela invalida intimações regularmente feitas antes de sua vigência?', answer: 'Não. Atos processuais já praticados e situações consolidadas são preservados. A lei nova rege, em regra, os atos futuros.', sources: [{ title: 'CPC, arts. 14 e 1.046 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm' }] },
  'dir3-17': { sections: [{ title: 'Desapropriação e procedimento', text: 'Desapropriação é intervenção supressiva da propriedade por necessidade ou utilidade pública ou interesse social, mediante indenização justa e, em regra, prévia e em dinheiro, ressalvadas hipóteses constitucionais. A declaração identifica o bem e o fundamento. Sem acordo sobre preço, a ação segue o Decreto-Lei 3.365/1941, com depósito e avaliação judicial. A imissão provisória na posse pode ocorrer mediante urgência declarada e depósito nos termos legais.' }, { title: 'Contestação, indenização e controle', text: 'Na ação, a contestação tem limites próprios e discute vícios do processo e impugnação do preço, sem converter o rito em revisão ampla do ato declaratório. O juiz fixa indenização considerando valor e elementos técnicos, com juros e correção conforme lei e precedentes. Desapropriação indireta ocorre quando o Poder Público se apropria do bem sem procedimento formal, sujeita à tutela indenizatória e regime prescricional definido pela legislação e jurisprudência.' }], question: 'Na desapropriação comum, a regra constitucional é indenização posterior e em títulos?', answer: 'Não. A regra geral é indenização justa, prévia e em dinheiro. Existem regimes constitucionais específicos com pagamento em títulos, como determinadas hipóteses de reforma agrária e política urbana.', sources: [{ title: 'Constituição Federal · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }, { title: 'Decreto-Lei 3.365/1941 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del3365.htm' }] },
  'dir3-18': { sections: [{ title: 'Ação civil pública', text: 'A ação civil pública tutela meio ambiente, consumidor, patrimônio cultural, ordem urbanística, ordem econômica e outros interesses difusos e coletivos previstos em lei. Legitimados incluem Ministério Público, Defensoria, entes públicos e associações que preencham requisitos legais. Pode pedir obrigação de fazer ou não fazer, tutela inibitória, reparação e medidas urgentes. Foro considera local do dano, com regras de competência e alcance territorial interpretadas conforme o microssistema e precedentes.' }, { title: 'Inquérito, TAC e sentença', text: 'O Ministério Público pode instaurar inquérito civil e requisitar informações. Compromisso de ajustamento de conduta firmado por legitimado produz título executivo extrajudicial. A sentença pode condenar genericamente à reparação de danos, seguida de liquidação e execução por legitimados ou vítimas conforme o direito. A coisa julgada segue o sistema coletivo do CDC, com diferenças para direitos difusos, coletivos e individuais homogêneos.' }], question: 'Uma associação pode propor ação civil pública sem cumprir requisitos legais de constituição e pertinência?', answer: 'Em regra, não. A associação deve atender aos requisitos legais de tempo de constituição e finalidade institucional, observadas dispensas legais e jurisprudenciais em situações específicas.', sources: [{ title: 'Lei 7.347/1985 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l7347orig.htm' }, { title: 'CDC · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm' }] },
  'dir3-19': { sections: [{ title: 'Mandado de segurança individual', text: 'Mandado de segurança protege direito líquido e certo não amparado por habeas corpus ou habeas data contra ilegalidade ou abuso de poder praticado por autoridade ou agente no exercício de atribuições públicas. Direito líquido e certo é demonstrável por prova pré-constituída, sem dilação probatória. O prazo decadencial é de 120 dias da ciência do ato. Não cabe contra lei em tese, decisão judicial com recurso próprio eficaz ou ato sujeito a recurso administrativo com efeito suspensivo independente de caução, conforme lei e jurisprudência.' }, { title: 'Coletivo e procedimento', text: 'Mandado de segurança coletivo pode ser impetrado por partido político com representação no Congresso e organização sindical, entidade de classe ou associação que atenda requisitos constitucionais e legais. Protege direitos coletivos ou individuais homogêneos de membros ou associados. A inicial deve indicar autoridade coatora e pessoa jurídica interessada. O juiz pode conceder liminar se houver fundamento relevante e risco de ineficácia da ordem. A sentença não substitui ação de cobrança de parcelas pretéritas.' }], question: 'O impetrante precisa produzir perícia complexa para demonstrar o direito no mandado de segurança?', answer: 'Em regra, não. A prova deve ser pré-constituída e o direito líquido e certo demonstrável documentalmente, sem dilação probatória.', sources: [{ title: 'Lei 12.016/2009 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2009/lei/l12016.htm' }, { title: 'Constituição, art. 5º · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }] },  'dir4-1': { sections: [{ title: 'Artigo 225 e dever ambiental', text: 'O art. 225 da Constituição reconhece a todos o direito ao meio ambiente ecologicamente equilibrado, bem de uso comum e essencial à sadia qualidade de vida. Impõe ao Poder Público e à coletividade o dever de defendê-lo e preservá-lo para presentes e futuras gerações. O §1º prevê deveres estatais como preservar processos ecológicos, proteger diversidade genética, definir espaços especialmente protegidos, exigir estudo prévio de impacto ambiental para obra ou atividade potencialmente causadora de significativa degradação, controlar técnicas de risco, promover educação ambiental e proteger fauna e flora.' }, { title: 'Competências e propriedade', text: 'O art. 23 estabelece competência administrativa comum para proteger o ambiente, combater poluição e preservar florestas, fauna e flora. A LC 140/2011 organiza cooperação. O art. 24 prevê competência legislativa concorrente em matéria ambiental. União edita normas gerais e Estados suplementam, podendo exercer competência plena na ausência de norma geral federal. Municípios legislam sobre interesse local e suplementam normas federais e estaduais, conforme art. 30. A propriedade deve cumprir função social, inclusive ambiental, nos arts. 5º, XXIII, 170, III e 186.' }], question: 'Um Estado pode editar regra de proteção mais rigorosa que norma federal geral, respeitadas as competências constitucionais?', answer: 'Em regra pode suplementar a norma geral para atender peculiaridades regionais, desde que não contrarie os parâmetros constitucionais e federais aplicáveis.', sources: [{ title: 'Constituição Federal · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }] },
  'dir4-2': { sections: [{ title: 'Política Nacional do Meio Ambiente', text: 'A Lei 6.938/1981 institui a PNMA e define meio ambiente, degradação, poluição, poluidor e recursos ambientais. Objetivos incluem preservar, melhorar e recuperar qualidade ambiental, compatibilizar desenvolvimento com equilíbrio ecológico e estabelecer critérios de qualidade. Instrumentos incluem padrões, zoneamento, avaliação de impactos, licenciamento, incentivos tecnológicos, criação de espaços protegidos, sistema de informações, Cadastro Técnico Federal e penalidades. O SISNAMA articula órgãos federais, estaduais e municipais, com CONAMA como órgão consultivo e deliberativo e IBAMA como executor federal.' }, { title: 'Licenciamento e responsabilidade', text: 'Atividade potencialmente poluidora ou capaz de causar degradação depende de licenciamento ambiental conforme a legislação e competência definida. Licenças não afastam responsabilidade civil objetiva pela reparação integral do dano, nem responsabilidades administrativa e penal. O Decreto 99.274/1990 regulamenta a PNMA e disciplina órgãos, licenciamento e padrões. O Código Estadual do Meio Ambiente de Mato Grosso, LC 38/1995, estrutura instrumentos e regras estaduais, devendo ser consultado em texto atualizado para licenças, fiscalização e proteção dos recursos.' }], question: 'A licença ambiental impede que o empreendedor seja responsabilizado por dano causado durante a atividade?', answer: 'Não. Licença não exclui responsabilidade civil objetiva de reparar dano, nem eventual sanção administrativa ou penal por conduta ilícita.', sources: [{ title: 'Lei 6.938/1981 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l6938.htm' }, { title: 'Decreto 99.274/1990 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/decreto/antigos/d99274.htm' }, { title: 'LC 38/1995 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }] },
  'dir4-3': { sections: [{ title: 'Cooperação e atribuições', text: 'A LC 140/2011 fixa normas de cooperação entre União, Estados, Distrito Federal e Municípios nas ações administrativas ambientais. Cada empreendimento é licenciado ou autorizado por um único ente, sem excluir manifestação dos demais dentro de suas atribuições. A União licencia hipóteses legais como atividades localizadas ou desenvolvidas conjuntamente no Brasil e país limítrofe, mar territorial, terras indígenas ou unidades de conservação federais, ressalvadas APAs. Estados licenciam o que não seja atribuição federal ou municipal. Municípios licenciam impacto local conforme tipologia definida pelo conselho estadual e atividades delegadas.' }, { title: 'Fiscalização e atuação supletiva', text: 'Todos os entes podem fiscalizar e lavrar auto de infração ambiental. Em regra, prevalece para fins de sanção o auto do órgão que detenha atribuição de licenciamento ou autorização. A atuação supletiva substitui o ente originariamente competente em hipóteses como inexistência de órgão ambiental capacitado ou conselho de meio ambiente. Atuação subsidiária é apoio técnico, científico, administrativo ou financeiro, solicitado pelo ente originário. Cooperação não elimina dever comum de proteção.' }], question: 'Se um município tem competência para licenciar atividade de impacto local, o Estado fica proibido de fiscalizar dano ambiental?', answer: 'Não. O dever de fiscalização é comum. A LC 140 estabelece coordenação e define efeitos dos autos, sem afastar a atuação fiscalizatória dos demais entes.', sources: [{ title: 'LC 140/2011 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp140.htm' }] },  'dir4-4': { sections: [{ title: 'Competência federal no licenciamento', text: 'A LC 140/2011 define a regra geral de licenciamento por um único ente e prevê hipóteses de competência federal. O Decreto 8.437/2015 tipifica empreendimentos cujo licenciamento é da União, como determinados empreendimentos de infraestrutura e atividades desenvolvidas em mais de um Estado, conforme porte e características descritos nos anexos. A localização em unidade de conservação federal, terra indígena, mar territorial ou país limítrofe também pode atrair atribuição federal segundo a lei. A tipologia não deve ser confundida com a regra de impacto direto: impacto ambiental significativo exige avaliação adequada, mas não determina sozinho a esfera licenciadora.' }, { title: 'Estudo do caso concreto', text: 'Identifique atividade, porte, potencial poluidor, localização e tipologia normativa. Verifique se há delegação ou atuação supletiva. A autoridade licenciadora pode solicitar manifestação de outros órgãos, que deve ser técnica e observar prazo legal. A decisão final considera o processo e não transfere automaticamente a competência. O empreendimento continua sujeito a fiscalização ambiental por outros entes.' }], question: 'Apenas o fato de uma atividade ser ambientalmente impactante torna federal todo o seu licenciamento?', answer: 'Não. A competência segue Constituição, LC 140 e tipologias do Decreto 8.437/2015. Impacto e porte importam, mas não substituem o enquadramento jurídico da atividade e localização.', sources: [{ title: 'Decreto 8.437/2015 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/decreto/d8437.htm' }, { title: 'LC 140/2011 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp140.htm' }] },
  'dir4-5': { sections: [{ title: 'Responsabilidade penal ambiental', text: 'A Lei 9.605/1998 tipifica crimes contra fauna, flora, poluição, ordenamento urbano, patrimônio cultural e administração ambiental. Pessoas físicas respondem conforme dolo ou culpa previstos no tipo. Pessoa jurídica pode ser responsabilizada quando a infração decorre de decisão de representante ou órgão colegiado, no interesse ou benefício da entidade, sem excluir pessoas físicas envolvidas. A responsabilização penal da pessoa jurídica não depende necessariamente de denúncia simultânea de pessoa física, conforme entendimento do STF.' }, { title: 'Sanções e acordos', text: 'Penas incluem privação de liberdade, multa e restrições de direitos, com alternativas legais para crimes de menor potencial ofensivo. A prestação de serviços à comunidade e a interdição de atividade podem ser aplicadas conforme tipo e circunstâncias. A transação penal e a suspensão condicional do processo seguem Lei 9.099/1995 e requisitos próprios. Reparação do dano tem relevância, mas não apaga automaticamente o crime. A lei prevê desconsideração da pessoa jurídica quando personalidade for obstáculo ao ressarcimento.' }], question: 'A pessoa jurídica pode responder criminalmente por crime ambiental sem identificar uma pessoa física denunciada junto com ela?', answer: 'Sim. O STF afastou a exigência de dupla imputação obrigatória. Ainda é necessário demonstrar que a infração decorreu de decisão institucional em benefício ou interesse da entidade, nos termos da lei.', sources: [{ title: 'Lei 9.605/1998 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9605.htm' }, { title: 'STF, RE 548.181', url: 'https://portal.stf.jus.br/' }] },
  'dir4-6': { sections: [{ title: 'Infrações administrativas', text: 'O Decreto 6.514/2008 regulamenta infrações e sanções administrativas ambientais federais. Infração administrativa é ação ou omissão que viole regras de uso, gozo, promoção, proteção e recuperação ambiental. Sanções incluem advertência, multa simples ou diária, apreensão, destruição ou inutilização de produtos, suspensão de venda ou fabricação, embargo, demolição, suspensão de atividade e restrições de direitos. A sanção deve considerar gravidade, antecedentes e situação econômica do infrator, com motivação e proporcionalidade.' }, { title: 'Auto, defesa e prescrição', text: 'O auto de infração identifica conduta, norma, local, data e autoria possível, e inicia processo com contraditório e ampla defesa. Medidas cautelares como embargo podem prevenir continuidade do dano, mas devem ser motivadas e submetidas ao processo. A prescrição punitiva ambiental federal tem regras próprias no Decreto 6.514 e na Lei 9.873/1999. Não confundir sanção administrativa com dever civil de reparar integralmente o dano, que possui regime independente.' }], question: 'O pagamento de multa ambiental substitui automaticamente a obrigação de recuperar a área degradada?', answer: 'Não. Sanção administrativa e reparação civil têm funções distintas. O infrator pode responder à multa e continuar obrigado a reparar integralmente o dano.', sources: [{ title: 'Decreto 6.514/2008 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6514.htm' }, { title: 'Lei 9.873/1999 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9873.htm' }] },
  'dir4-7': { sections: [{ title: 'Processo estadual em Mato Grosso', text: 'O Decreto Estadual 1.436/2022 disciplina a apuração de infrações administrativas ambientais no âmbito da SEMA-MT e deve ser estudado em sua versão consolidada, junto da LC 38/1995 e da Lei Estadual 7.692/2002. O processo começa com fiscalização e auto de infração, com identificação da conduta, dispositivo violado, sanção e circunstâncias. O autuado deve ser cientificado e pode apresentar defesa e provas nos prazos e formas previstos no decreto.' }, { title: 'Instrução, decisão e recursos', text: 'A autoridade instrui o processo, avalia prova e circunstâncias, verifica reincidência e agravantes ou atenuantes e decide motivadamente. O interessado pode recorrer às instâncias administrativas definidas no regulamento, observando competência, prazo e efeitos. A ausência de defesa não dispensa a Administração de verificar legalidade e materialidade. Medidas de reparação ambiental podem tramitar articuladas, sem substituir sanção. Em prova, atenção a prazos, autoridade julgadora, critérios de cálculo e hipóteses de nulidade do texto estadual vigente.' }], question: 'A revelia do autuado obriga a autoridade ambiental a confirmar automaticamente a multa?', answer: 'Não. A Administração deve verificar materialidade, autoria, enquadramento legal, competência e regularidade do processo, e motivar sua decisão, mesmo sem defesa apresentada.', sources: [{ title: 'Decreto Estadual 1.436/2022 · Diário Oficial de MT', url: 'https://www.iomat.mt.gov.br/' }, { title: 'Lei Estadual 7.692/2002 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }] },
  'dir4-8': { sections: [{ title: 'Conciliação ambiental e NUCAM', text: 'A conciliação ambiental busca solução célere e adequada para infrações e reparação, sem afastar legalidade, proteção do ambiente e devido processo. No âmbito da SEMA-MT, o NUCAM atua conforme Instrução Normativa 02/2023 e regras estaduais aplicáveis. A sessão permite esclarecer fatos, consequências e alternativas legais. O comparecimento e a negociação não equivalem automaticamente à confissão nem eliminam direitos de defesa fora dos limites normativos.' }, { title: 'Compromissos e limites', text: 'A composição deve respeitar competência, critérios objetivos e forma previstos na norma, incluindo pagamento ou parcelamento de multa quando admitidos e medidas de recuperação ou compensação. O compromisso precisa ser registrado, acompanhado e compatível com reparação integral. Descumprimento pode acarretar retomada do processo ou execução do ajuste conforme instrumento. A conciliação administrativa não impede responsabilização civil, penal ou novas sanções por fatos distintos.' }], question: 'A conciliação de uma multa ambiental elimina o dever de recuperar dano comprovado?', answer: 'Não necessariamente. Multa e reparação do dano são obrigações distintas. O acordo deve tratar das medidas previstas e não pode afastar a reparação integral quando devida.', sources: [{ title: 'IN SEMA-MT 02/2023 · Diário Oficial de MT', url: 'https://www.iomat.mt.gov.br/' }, { title: 'Lei 9.605/1998 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9605.htm' }] },  'dir4-9': { sections: [{ title: 'Política Nacional de Recursos Hídricos', text: 'A Lei 9.433/1997 reconhece a água como bem de domínio público, recurso limitado e dotado de valor econômico. Em escassez, prioridade é consumo humano e dessedentação animal. A gestão deve proporcionar usos múltiplos, ter bacia hidrográfica como unidade territorial e ser descentralizada e participativa. Instrumentos incluem planos de recursos hídricos, enquadramento dos corpos d’água, outorga, cobrança e sistema de informações. A outorga controla usos e não transfere propriedade da água.' }, { title: 'Regime estadual de Mato Grosso', text: 'A legislação estadual organiza gestão das águas no território e articula órgãos, comitês de bacia e usuários. O edital cita a Lei Estadual 11.088/2020, cujo texto consolidado deve ser estudado para competências, instrumentos, outorga, cobrança e infrações estaduais. Diferencie domínio da água, que depende da Constituição, de competência administrativa para gerir e conceder outorga. Planos e enquadramento orientam usos e metas de qualidade.' }], question: 'A outorga de uso de água transfere a propriedade do recurso ao usuário?', answer: 'Não. A outorga confere direito de uso por prazo e condições definidos, mantendo a água como bem público e sujeito à gestão integrada.', sources: [{ title: 'Lei 9.433/1997 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9433.htm' }, { title: 'Lei Estadual 11.088/2020 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }] },
  'dir4-10': { sections: [{ title: 'Política Nacional de Segurança de Barragens', text: 'A Lei 12.334/2010 institui a PNSB para barragens destinadas à acumulação de água, disposição de rejeitos ou resíduos industriais, conforme critérios de altura, volume, dano potencial associado e categoria de risco. A Lei 14.066/2020 alterou o regime, ampliando obrigações de prevenção e transparência. O empreendedor é responsável pela segurança, deve manter plano de segurança, inspeções, revisões periódicas e plano de ação de emergência quando exigido.' }, { title: 'Fiscalização e emergência', text: 'A entidade fiscalizadora varia conforme finalidade, uso e domínio do recurso. O SNISB integra informações. Classificação de risco considera aspectos técnicos e probabilidade de falha. Dano potencial associado considera consequências a jusante e não equivale à probabilidade de rompimento. O Decreto 11.310/2022 regulamenta dispositivos da PNSB e detalha cadastro, planos, inspeções e articulação de emergência. Comunidades e autoridades devem receber informação conforme plano e risco.' }], question: 'Categoria de risco e dano potencial associado medem exatamente o mesmo aspecto da barragem?', answer: 'Não. Categoria de risco examina características que influenciam probabilidade de acidente. Dano potencial associado estima consequências de eventual ruptura ou mau funcionamento.', sources: [{ title: 'Lei 12.334/2010 atualizada · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l12334.htm' }, { title: 'Decreto 11.310/2022 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2022/decreto/D11310.htm' }] },
  'dir4-11': { sections: [{ title: 'Áreas protegidas pelo Código Florestal', text: 'A Lei 12.651/2012 protege vegetação nativa e institui APP e Reserva Legal. APP protege funções como recursos hídricos, estabilidade geológica, biodiversidade e conectividade, em áreas marginais, nascentes, encostas e outras hipóteses legais. Reserva Legal é área no imóvel rural destinada ao uso sustentável e conservação, com percentuais que variam conforme localização e bioma, além de regras específicas para Amazônia Legal. Não confundir APP com Reserva Legal, pois podem coexistir no mesmo imóvel.' }, { title: 'CAR, regularização e uso consolidado', text: 'O Cadastro Ambiental Rural é registro eletrônico obrigatório que reúne informações ambientais do imóvel, mas não constitui título de propriedade. O PRA permite regularização ambiental nas condições legais. A lei prevê regras para áreas rurais consolidadas antes de 22 de julho de 2008, com recomposição diferenciada em certas situações. Supressão de vegetação depende de autorização e respeito a áreas protegidas. Cota de Reserva Ambiental pode compensar déficit nos termos legais, observados equivalência e localização.' }], question: 'A inscrição do imóvel no CAR prova domínio ou posse civil da propriedade?', answer: 'Não. O CAR é cadastro ambiental declaratório e não serve como título para reconhecimento de propriedade ou posse.', sources: [{ title: 'Lei 12.651/2012 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12651.htm' }] },
  'dir4-12': { sections: [{ title: 'SNUC e categorias', text: 'A Lei 9.985/2000 organiza unidades de conservação em proteção integral e uso sustentável. Proteção integral admite apenas uso indireto dos recursos naturais, salvo exceções legais. Inclui estação ecológica, reserva biológica, parque, monumento natural e refúgio de vida silvestre. Uso sustentável compatibiliza conservação e uso sustentável, incluindo APA, ARIE, floresta nacional, reserva extrativista, reserva de fauna, RDS e RPPN. Cada categoria tem objetivos e regras próprios.' }, { title: 'Criação, gestão e entorno', text: 'Unidade é criada por ato do Poder Público após estudos técnicos e consulta pública, exceto categorias com regras específicas de consulta, como estação ecológica e reserva biológica. Limites só são alterados por lei e redução exige lei específica. Plano de manejo orienta zoneamento e usos e deve ser elaborado no prazo legal. Conselho consultivo ou deliberativo varia conforme a categoria. Zona de amortecimento reduz impactos externos, observadas regras legais.' }], question: 'Toda unidade de conservação deve permitir visitação pública?', answer: 'Não. Estação ecológica e reserva biológica têm visitação fortemente restrita a objetivos educacionais e de pesquisa previstos em lei. O regime depende da categoria.', sources: [{ title: 'Lei 9.985/2000 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9985.htm' }, { title: 'Decreto 4.340/2002 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/decreto/2002/d4340.htm' }] },
  'dir4-13': { sections: [{ title: 'Sistema Estadual de Unidades de Conservação', text: 'A Lei Estadual 9.502/2011 institui o SEUC de Mato Grosso e deve ser lida junto ao SNUC, verificando categorias estaduais, objetivos, criação, gestão e participação social. O sistema articula áreas estaduais e demais unidades reconhecidas, preservando competências dos entes. Unidades podem ser de proteção integral ou uso sustentável segundo a disciplina legal. O ato de criação delimita área e objetivos e a gestão deve elaborar instrumentos de manejo e fiscalização.' }, { title: 'Aplicação e compatibilidade', text: 'Ao analisar uma unidade, identifique ente criador, categoria, domínio fundiário, usos permitidos, conselho, plano de manejo e zona de amortecimento. A lei estadual deve respeitar normas gerais federais do SNUC, podendo suplementar peculiaridades regionais. Alteração de limites, desafetação e redução devem observar reserva legal quando exigida e consulta pública nos casos aplicáveis.' }], question: 'A criação de uma unidade estadual dispensa plano de manejo e regras de uso?', answer: 'Não. A criação deve ser seguida de gestão conforme categoria, com plano de manejo e regras legais para compatibilizar proteção e usos permitidos.', sources: [{ title: 'Lei Estadual 9.502/2011 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }, { title: 'Lei 9.985/2000 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9985.htm' }] },
  'dir4-14': { sections: [{ title: 'Política Nacional de Resíduos Sólidos', text: 'A Lei 12.305/2010 estabelece prevenção, redução, reutilização, reciclagem, tratamento e disposição final ambientalmente adequada. Distingue resíduo, que pode ter aproveitamento, de rejeito, cuja recuperação é inviável nas tecnologias disponíveis. A responsabilidade é compartilhada pelo ciclo de vida do produto entre fabricantes, importadores, distribuidores, comerciantes, consumidores e titulares de limpeza urbana. Logística reversa é instrumento para retorno de produtos e embalagens após uso.' }, { title: 'Planos e hierarquia', text: 'Planos nacional, estaduais, microrregionais e municipais orientam gestão, metas e responsabilidades. Geradores de resíduos perigosos e atividades específicas elaboram plano de gerenciamento. Municípios devem estruturar coleta seletiva e disposição de rejeitos em aterros licenciados. Lixões são incompatíveis com disposição ambientalmente adequada. O Decreto 10.936/2022 regulamenta a política e disciplina planos, logística reversa, sistemas de informação e instrumentos econômicos.' }], question: 'Na hierarquia da PNRS, a disposição final é a primeira opção para qualquer resíduo?', answer: 'Não. A ordem prioriza não geração, redução, reutilização, reciclagem e tratamento. Disposição final ambientalmente adequada é destinada aos rejeitos.', sources: [{ title: 'Lei 12.305/2010 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2010/lei/l12305.htm' }, { title: 'Decreto 10.936/2022 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2022/decreto/D10936.htm' }] },  'dir4-15': { sections: [{ title: 'EIA e RIMA', text: 'A Resolução CONAMA 1/1986 considera impacto ambiental alterações físicas, químicas e biológicas causadas por atividades que afetem saúde, segurança, atividades sociais, biota, condições estéticas e qualidade dos recursos. Para atividades modificadoras com significativa degradação, exige estudo de impacto ambiental e relatório de impacto ambiental. O EIA analisa alternativas tecnológicas e locacionais, inclusive não execução, identifica impactos nas fases do projeto, define área de influência, avalia medidas mitigadoras e propõe monitoramento. O RIMA comunica conclusões em linguagem acessível e mapas, gráficos e quadros.' }, { title: 'Licenciamento e audiência', text: 'A Resolução CONAMA 237/1997 define licenciamento como procedimento administrativo e licença como ato que estabelece condições, restrições e medidas de controle. Licença prévia avalia localização e concepção, licença de instalação autoriza implantação e licença de operação autoriza funcionamento após verificação de requisitos. O procedimento exige publicidade e participação nos casos previstos. Audiência pública não substitui análise técnica nem decisão do órgão, mas permite informações e manifestações sociais.' }], question: 'RIMA pode omitir alternativas locacionais porque o EIA já analisou o tema?', answer: 'Não. O EIA deve analisar alternativas e o RIMA deve refletir suas conclusões de modo acessível, para permitir compreensão pública do estudo.', sources: [{ title: 'Resolução CONAMA 1/1986 · MMA', url: 'https://conama.mma.gov.br/' }, { title: 'Resolução CONAMA 237/1997 · MMA', url: 'https://conama.mma.gov.br/' }] },
  'dir4-16': { sections: [{ title: 'Audiência pública ambiental', text: 'A Resolução CONAMA 9/1987 disciplina audiência pública no licenciamento quando o órgão julgar necessário ou quando solicitada por entidade civil, Ministério Público ou grupo de pelo menos cinquenta cidadãos. A finalidade é expor o conteúdo do projeto e do RIMA, esclarecer dúvidas e recolher críticas e sugestões. A ata e seus anexos subsidiam a análise e devem integrar o processo. Se solicitada e não realizada, a licença concedida pode ser inválida segundo a resolução.' }, { title: 'Participação e efeito', text: 'A audiência é pública e deve ocorrer em local acessível aos interessados. O empreendedor apresenta o projeto e a equipe técnica esclarece o estudo. A participação não equivale a plebiscito nem torna a decisão vinculada a uma maioria, mas exige consideração motivada das contribuições relevantes. O órgão pode realizar mais de uma audiência diante da localização e complexidade dos impactos.' }], question: 'A audiência pública escolhe diretamente se a licença será concedida?', answer: 'Não. Ela amplia informação e participação. A decisão é do órgão licenciador, que deve analisar o processo e motivar sua conclusão.', sources: [{ title: 'Resolução CONAMA 9/1987 · MMA', url: 'https://conama.mma.gov.br/' }] },
  'dir4-17': { sections: [{ title: 'Acesso ao patrimônio genético', text: 'A Lei 13.123/2015 regula acesso ao patrimônio genético brasileiro, conhecimento tradicional associado e repartição de benefícios. Patrimônio genético abrange informação de origem genética de espécies encontradas no território nacional, águas sob jurisdição e outros ambientes previstos em lei. Acesso é pesquisa ou desenvolvimento tecnológico realizado sobre amostra. Conhecimento tradicional associado pode ter origem identificável ou não identificável e envolve patrimônio genético segundo a lei.' }, { title: 'Cadastro, consentimento e repartição', text: 'Pesquisa e desenvolvimento devem ser cadastrados no SisGen antes de marcos legais como remessa ao exterior, divulgação de resultados, pedido de propriedade intelectual ou comercialização, conforme o caso. Acesso a conhecimento tradicional de origem identificável requer consentimento prévio informado. Exploração econômica de produto acabado ou material reprodutivo pode gerar repartição de benefícios monetária ou não monetária, observadas exceções legais. O Decreto 8.772/2016 regulamenta cadastro, notificações, fiscalização e repartição.' }], question: 'Qualquer pesquisa acadêmica com espécie brasileira exige autorização prévia individual do IBAMA?', answer: 'O regime geral da Lei 13.123 prevê cadastro no SisGen e requisitos próprios, não uma autorização individual genérica do IBAMA. A obrigação concreta depende da atividade, acesso, remessa e demais enquadramentos legais.', sources: [{ title: 'Lei 13.123/2015 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13123.htm' }, { title: 'Decreto 8.772/2016 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/decreto/D8772.htm' }] },
  'dir4-18': { sections: [{ title: 'Proteção da fauna', text: 'A Lei 5.197/1967 protege fauna silvestre e restringe utilização, perseguição, destruição, caça ou captura, conforme exceções e autorizações legais. A fauna é bem de interesse público e sua proteção se articula com art. 225, Lei 9.605/1998 e normas estaduais. Caça profissional é vedada. Caça amadora depende das condições e autorizações previstas em lei e decisões aplicáveis. Espécies exóticas e invasoras podem receber tratamento administrativo específico, sem afastar regras de bem-estar e proteção.' }, { title: 'Condutas e fiscalização', text: 'A captura, manutenção em cativeiro, transporte e comércio de espécimes ou produtos dependem de autorização ou origem legal. A apreensão de animais deve considerar destinação adequada, reabilitação e soltura tecnicamente segura. Infrações podem gerar sanções administrativas e crimes previstos na Lei 9.605/1998, sem prejuízo de reparação do dano. Em casos de subsistência e circunstâncias pessoais, a lei prevê disciplina própria, sem autorização geral para captura.' }], question: 'Encontrar animal silvestre em cativeiro com alegação de estimação antiga torna automaticamente regular a posse?', answer: 'Não. A posse depende de origem e autorização conforme a legislação. A autoridade deve apurar circunstâncias e definir destinação adequada, sem presumir regularidade apenas pela antiguidade.', sources: [{ title: 'Lei 5.197/1967 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l5197.htm' }, { title: 'Lei 9.605/1998 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9605.htm' }] },
  'dir4-19': { sections: [{ title: 'Serviços ambientais em Mato Grosso', text: 'A Lei Estadual 12.829/2025 institui a Política Estadual de Serviços Ambientais de Mato Grosso. Serviços ambientais são atividades individuais ou coletivas que favorecem manutenção, recuperação ou melhoria de serviços ecossistêmicos. A política busca reconhecer provedores, criar instrumentos de incentivo e apoiar conservação, restauração e uso sustentável. Para a prova, identificar conceitos, princípios, instrumentos, governança, fontes de recursos, critérios de elegibilidade e salvaguardas diretamente no texto legal estadual atualizado.' }, { title: 'Relação com pagamento por serviços ambientais', text: 'Serviço ecossistêmico é benefício fornecido pelos ecossistemas, como regulação hídrica, estoque de carbono, polinização e conservação da biodiversidade. Serviço ambiental é ação humana que mantém ou melhora esses benefícios. Pagamento por serviços ambientais é transação voluntária condicionada a resultados ou práticas verificáveis e segue também a Lei Federal 14.119/2021. Cadastro, monitoramento, adicionalidade, permanência e prevenção de dupla contagem são pontos relevantes de desenho e controle.' }], question: 'Serviço ecossistêmico e serviço ambiental são sinônimos perfeitos?', answer: 'Não. O ecossistêmico é benefício da natureza para pessoas e sociedade. Serviço ambiental designa ação humana que contribui para manter ou melhorar esses benefícios.', sources: [{ title: 'Lei Estadual 12.829/2025 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }, { title: 'Lei Federal 14.119/2021 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/L14119.htm' }] },
  'dir4-20': { sections: [{ title: 'Política da pesca em Mato Grosso', text: 'A Lei Estadual 9.096/2009 disciplina a política da pesca no Estado, incluindo conservação dos recursos pesqueiros, ordenamento, licenças, categorias de pesca e fiscalização. O estudo deve distinguir pesca de subsistência, amadora, profissional e científica conforme definições legais, verificando petrechos, cotas, períodos de defeso, locais proibidos e espécies protegidas. Regras podem ser complementadas por atos anuais e alterações legais, por isso o texto consolidado e atos vigentes da SEMA são essenciais.' }, { title: 'Ordenamento e sanções', text: 'O ordenamento considera ciclos reprodutivos, estoques, bacias e participação de usuários. Defeso restringe captura em períodos críticos e pode coexistir com regras federais. Licença não autoriza método, espécie ou local proibido. Infrações podem gerar apreensão, multa e outras consequências administrativas, além de responsabilidade penal e reparação ambiental. Em questão prática, identifique primeiro categoria do pescador, local, época, espécie e equipamento utilizado.' }], question: 'A licença de pesca amadora permite pescar espécie protegida durante o defeso?', answer: 'Não. A licença não afasta proibição de espécie, período ou local estabelecida em norma de proteção e ordenamento.', sources: [{ title: 'Lei Estadual 9.096/2009 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }, { title: 'Lei 9.605/1998 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9605.htm' }] },  'dir4-21': { sections: [{ title: 'Lei Estadual 8.830/2008 e proteção do Pantanal', text: 'A Lei 8.830/2008 institui política estadual de gestão e proteção da Bacia do Alto Paraguai em Mato Grosso. O regime busca conciliar conservação do Pantanal, atividades econômicas compatíveis, manutenção do pulso de inundação e proteção de áreas úmidas. A bacia reúne planalto e planície, de modo que intervenções a montante podem alterar sedimentos, vazões e ciclos de cheia a jusante. O estudo deve identificar zonas, usos admitidos, restrições, licenciamento e instrumentos de gestão previstos no texto consolidado.' }, { title: 'Regulamentação e aplicação', text: 'O Decreto Estadual 774/2024 regulamenta a política e detalha procedimentos e critérios. Para resolver questões, diferencie a bacia hidrográfica do bioma, examine a localização do empreendimento, o tipo de intervenção e seus efeitos cumulativos. A análise deve observar normas federais, estaduais e municipais, além de licenciamento e autorizações setoriais. A proteção do Pantanal depende de gestão integrada entre planalto e planície e de consideração dos regimes de inundação.' }], question: 'Uma intervenção situada no planalto pode ser irrelevante para o Pantanal por estar fora da planície inundável?', answer: 'Não necessariamente. A conectividade hidrológica da Bacia do Alto Paraguai permite que intervenções a montante afetem vazão, sedimentos e cheias na planície. A avaliação deve considerar efeitos na bacia.', sources: [{ title: 'Lei Estadual 8.830/2008 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }, { title: 'Decreto Estadual 774/2024 · Diário Oficial MT', url: 'https://www.iomat.mt.gov.br/' }] },
  'dir4-22': { sections: [{ title: 'Política Nacional de Pagamento por Serviços Ambientais', text: 'A Lei 14.119/2021 institui a PNPSA e define pagamento por serviços ambientais como transação voluntária em que um pagador transfere recursos ou benefícios a provedor que mantém, recupera ou melhora serviços ecossistêmicos, conforme condições pactuadas. Princípios incluem provedor-recebedor, usuário-pagador, transparência, participação e reconhecimento de povos e comunidades tradicionais. Modalidades podem ser pagamento direto, melhorias sociais, títulos, créditos ou compensações, observada a lei.' }, { title: 'Programa e contrato', text: 'O Programa Federal de PSA prioriza áreas relevantes para conservação, água, biodiversidade e carbono, segundo critérios legais. O contrato deve identificar partes, objeto, área, serviços, indicadores, monitoramento, prazo e consequências do descumprimento. A adicionalidade verifica o benefício ambiental adicional em relação ao cenário de referência. Permanência, vazamento e dupla contagem são riscos a tratar. A participação voluntária não dispensa cadastro, regularidade e salvaguardas aplicáveis.' }], question: 'O pagamento por serviços ambientais é uma multa paga pelo poluidor?', answer: 'Não. É incentivo ou transação voluntária condicionada à provisão de serviços ambientais. Multa é sanção decorrente de infração e tem natureza distinta.', sources: [{ title: 'Lei 14.119/2021 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/L14119.htm' }] },
  'dir4-23': { sections: [{ title: 'Compensação ambiental no licenciamento', text: 'A compensação ambiental do art. 36 da Lei 9.985/2000 incide sobre empreendimento de significativo impacto ambiental, assim considerado com fundamento em EIA/RIMA. O empreendedor apoia implantação e manutenção de unidade de conservação do grupo de proteção integral, conforme prioridades legais, podendo beneficiar unidades afetadas ou outras definidas pelo órgão licenciador. A medida não substitui prevenção, mitigação e reparação de danos.' }, { title: 'Câmara de Compensação Ambiental de Mato Grosso', text: 'O Decreto Estadual 2.594/2014 disciplina a Câmara de Compensação Ambiental em Mato Grosso, incluindo deliberação sobre destinação e aplicação dos recursos. O cálculo considera grau de impacto e limites legais definidos pelo STF, com análise vinculada ao EIA/RIMA. É importante separar compensação ambiental de compensação por supressão de vegetação, reposição florestal, reparação civil e multas, pois cada instituto tem fato gerador e finalidade próprios.' }], question: 'Pagamento de compensação ambiental extingue automaticamente o dever de reparar dano específico causado pelo empreendimento?', answer: 'Não. Compensação do licenciamento não substitui obrigações de prevenir, mitigar ou reparar dano concreto nem outras compensações legalmente exigíveis.', sources: [{ title: 'Lei 9.985/2000, art. 36 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l9985.htm' }, { title: 'Decreto Estadual 2.594/2014 · Diário Oficial MT', url: 'https://www.iomat.mt.gov.br/' }] },
  'dir4-24': { sections: [{ title: 'Política Nacional sobre Mudança do Clima', text: 'A Lei 12.187/2009 estabelece princípios, objetivos, diretrizes e instrumentos para enfrentar mudança do clima e compatibilizar desenvolvimento e proteção climática. Reconhece prevenção, precaução, participação, desenvolvimento sustentável e responsabilidades comuns, porém diferenciadas. Instrumentos incluem Plano Nacional sobre Mudança do Clima, Fundo Clima, inventários, registro de emissões, avaliação de impactos e medidas de adaptação. A política busca reduzir emissões e fortalecer sumidouros, articulando entes e setores.' }, { title: 'Mitigação, adaptação e metas', text: 'Mitigação reduz emissões ou aumenta remoções de gases de efeito estufa. Adaptação diminui vulnerabilidade e eleva resiliência a impactos atuais e projetados. A lei prevê compromisso nacional voluntário de redução em relação a projeções, cuja implementação depende de planos e atos posteriores. Inventários usam fontes, setores e metodologias consistentes. Não confunda meta climática nacional com autorização automática para atividade emissora.' }], question: 'Uma medida de adaptação e uma de mitigação têm o mesmo objetivo imediato?', answer: 'Não. Adaptação reduz vulnerabilidade aos efeitos climáticos. Mitigação limita as causas ao reduzir emissões ou ampliar remoções de gases de efeito estufa.', sources: [{ title: 'Lei 12.187/2009 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2009/lei/l12187.htm' }, { title: 'Acordo de Paris promulgado · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/decreto/d9073.htm' }] },
  'dir4-25': { sections: [{ title: 'Fundo Nacional sobre Mudança do Clima', text: 'A Lei 12.114/2009 cria o Fundo Nacional sobre Mudança do Clima, de natureza contábil, vinculado ao órgão federal competente. O Fundo financia projetos, estudos e empreendimentos de mitigação e adaptação. Possui modalidades reembolsável, operada por agente financeiro, e não reembolsável, gerida diretamente conforme governança legal. Recursos e prioridades seguem plano anual, orçamento, critérios técnicos e deliberação do comitê gestor.' }, { title: 'Acesso e controle', text: 'Projetos devem demonstrar elegibilidade, impacto climático, viabilidade e conformidade socioambiental. Financiamento reembolsável gera obrigação de pagamento e segue condições do agente financeiro. Apoio não reembolsável observa chamada, seleção e prestação de contas. Transparência, monitoramento de resultados e controle público permitem verificar uso dos recursos e contribuição para política climática.' }], question: 'Todo recurso do Fundo Clima é concedido como empréstimo?', answer: 'Não. A lei prevê modalidades reembolsável e não reembolsável, com operação e critérios distintos.', sources: [{ title: 'Lei 12.114/2009 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l12114.htm' }] },
  'dir4-26': { sections: [{ title: 'Decreto 9.578/2018', text: 'O Decreto 9.578/2018 consolida atos regulamentares relativos ao Fundo Nacional sobre Mudança do Clima e à Política Nacional sobre Mudança do Clima. Deve ser lido em conjunto com as Leis 12.114/2009 e 12.187/2009. O decreto organiza disposições sobre objetivos e fontes do Fundo, modalidades de financiamento, comitê gestor, aplicação de recursos e instrumentos climáticos. Sendo regulamento, detalha execução da lei e não pode contrariar nem ampliar seus limites.' }, { title: 'Relação com a governança climática', text: 'A governança envolve planejamento, coordenação, financiamento e acompanhamento de políticas de mitigação e adaptação. O comitê gestor define diretrizes e prioridades dentro da competência normativa. A prova pode cobrar distinção entre lei instituidora, decreto regulamentador e atos de execução, bem como relação entre financiamento e resultados climáticos mensuráveis.' }], question: 'Um decreto regulamentador pode alterar a finalidade legal do Fundo Clima?', answer: 'Não. O regulamento detalha a execução da lei dentro de seus limites, sem inovar contra o texto legal ou modificar finalidade definida pelo legislador.', sources: [{ title: 'Decreto 9.578/2018 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/decreto/D9578.htm' }, { title: 'Lei 12.114/2009 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/leis/l12114.htm' }] },
  'dir4-27': { sections: [{ title: 'Política Estadual de Mudanças Climáticas', text: 'A LC Estadual 582/2017 institui a política climática de Mato Grosso, com objetivos de mitigação, adaptação, redução de vulnerabilidade e desenvolvimento de baixo carbono. O texto deve ser estudado quanto a princípios, instrumentos, planos, inventários, metas, governança e participação. Setores como mudança do uso da terra, agropecuária, energia, resíduos e processos industriais são relevantes para emissões estaduais e desenho de ações.' }, { title: 'Implementação e integração', text: 'Políticas estaduais articulam-se à PNMC e ao Acordo de Paris, respeitando competências e compromissos nacionais. Inventários permitem identificar fontes e medir tendência, enquanto planos orientam medidas e indicadores. Adaptação avalia riscos regionais como secas, incêndios, cheias e impactos sobre agricultura e biodiversidade. Para provas, verifique atualizações regulamentares e programas vigentes de Mato Grosso, além do texto da LC.' }], question: 'Inventário estadual de emissões é apenas uma lista sem utilidade para planejamento?', answer: 'Não. O inventário quantifica fontes e remoções segundo metodologia, apoiando definição de prioridades, metas e monitoramento das medidas climáticas.', sources: [{ title: 'LC Estadual 582/2017 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }, { title: 'Lei 12.187/2009 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2009/lei/l12187.htm' }] },  'dir4-28': { sections: [{ title: 'Política Estadual de Educação Ambiental', text: 'A Lei Estadual 10.903/2019 institui a Política Estadual de Educação Ambiental de Mato Grosso. Educação ambiental é componente essencial e permanente da educação, presente de forma articulada em todos os níveis e modalidades, formal e não formal. A política promove compreensão integrada do ambiente, participação, consciência crítica, sustentabilidade e valorização de conhecimentos locais. O Decreto 938/2024 regulamenta a lei e detalha implementação, articulação institucional e ações educativas.' }, { title: 'Educação formal e não formal', text: 'No ensino formal, educação ambiental deve integrar currículo de maneira contínua e interdisciplinar, sem se restringir a disciplina isolada, ressalvadas hipóteses legais de pós-graduação e formação específica. No campo não formal, inclui campanhas, comunicação, participação social, sensibilização e formação de comunidades. Órgãos públicos, escolas, empresas e sociedade têm papéis complementares. A política deve ser permanente e adequada aos contextos socioambientais de Mato Grosso.' }], question: 'A política de educação ambiental exige que o tema seja oferecido apenas como disciplina independente?', answer: 'Não. A regra é abordagem integrada, contínua e interdisciplinar, articulando diferentes áreas e níveis educativos.', sources: [{ title: 'Lei Estadual 10.903/2019 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }, { title: 'Decreto Estadual 938/2024 · Diário Oficial MT', url: 'https://www.iomat.mt.gov.br/' }] },
  'dir4-29': { sections: [{ title: 'Diretrizes nacionais de saneamento', text: 'A Lei 11.445/2007 estabelece diretrizes nacionais para saneamento básico. Abrange abastecimento de água potável, esgotamento sanitário, limpeza urbana e manejo de resíduos sólidos, drenagem e manejo de águas pluviais urbanas. Princípios incluem universalização, integralidade, eficiência, sustentabilidade econômica, transparência, controle social e segurança. Titulares formulam política e planos, prestam ou delegam serviços e definem entidade reguladora.' }, { title: 'Planejamento e prestação', text: 'Planos de saneamento diagnosticam situação, estabelecem metas, programas e ações, indicadores, emergências e fontes de financiamento. A prestação pode ser direta ou delegada segundo legislação e contrato. A regulação estabelece padrões e tarifas, e a fiscalização verifica cumprimento. A cobrança deve assegurar sustentabilidade e acesso, com subsídios previstos. O controle social garante participação no planejamento e avaliação.' }], question: 'Quais quatro componentes integram o saneamento básico na Lei 11.445?', answer: 'Abastecimento de água, esgotamento sanitário, limpeza urbana e manejo de resíduos sólidos, e drenagem e manejo das águas pluviais urbanas.', sources: [{ title: 'Lei 11.445/2007 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2007/lei/l11445.htm' }] },
  'dir4-30': { sections: [{ title: 'Marco legal do saneamento', text: 'A Lei 14.026/2020 atualizou o marco do saneamento, reforçando metas de universalização, regionalização, competição por contratos, regulação de referência pela ANA e exigências de capacidade econômico-financeira. Os contratos devem prever metas para atender 99% da população com água potável e 90% com coleta e tratamento de esgoto até 2033, ressalvadas condições legais de extensão. Novos contratos dependem de licitação quando há prestação regionalizada ou delegação, segundo regras aplicáveis.' }, { title: 'Regionalização e regulação', text: 'A prestação regionalizada agrupa municípios para viabilizar escala, subsídios cruzados e universalização. Estados podem estruturar regiões metropolitanas, aglomerações, microrregiões ou unidades regionais de saneamento. A ANA edita normas de referência para regulação, sem substituir reguladores locais. Contratos de programa sem licitação tiveram restrições e regras de transição. A análise deve distinguir titularidade, prestação, regulação e planejamento.' }], question: 'A ANA passa a fiscalizar diretamente todos os serviços municipais de saneamento?', answer: 'Não. A ANA estabelece normas de referência para regulação. A regulação e fiscalização direta permanecem com entidades reguladoras competentes, conforme arranjo local.', sources: [{ title: 'Lei 14.026/2020 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2020/lei/l14026.htm' }, { title: 'Lei 11.445/2007 atualizada · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2007/lei/l11445.htm' }] },
  'dir4-31': { sections: [{ title: 'Convenções ambientais', text: 'A Convenção de Estocolmo busca proteger saúde humana e ambiente contra poluentes orgânicos persistentes, restringindo produção, uso, importação e exportação de substâncias listadas e prevendo eliminação ou redução, com exceções controladas. A Convenção de Ramsar promove conservação e uso racional de zonas úmidas e designação de sítios de importância internacional. A Convenção sobre Diversidade Biológica tem objetivos de conservar biodiversidade, usar sustentavelmente seus componentes e repartir de modo justo benefícios de recursos genéticos.' }, { title: 'Acordo de Paris e implementação', text: 'O Acordo de Paris busca manter o aumento da temperatura média global bem abaixo de 2°C e envidar esforços para limitá-lo a 1,5°C. Partes apresentam contribuições nacionalmente determinadas, atualizadas progressivamente, e adotam medidas de mitigação e adaptação. Transparência e balanço global acompanham progresso. Tratados promulgados integram o ordenamento interno nos termos constitucionais. Interprete obrigações considerando texto, promulgação brasileira e legislação doméstica.' }], question: 'Ramsar é tratado centrado na proteção de zonas úmidas ou na eliminação de poluentes orgânicos persistentes?', answer: 'Ramsar trata de zonas úmidas. A Convenção de Estocolmo trata de poluentes orgânicos persistentes.', sources: [{ title: 'Convenção de Estocolmo · ONU', url: 'https://www.pops.int/' }, { title: 'Convenção de Ramsar', url: 'https://www.ramsar.org/' }, { title: 'Acordo de Paris promulgado · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/decreto/d9073.htm' }, { title: 'Convenção sobre Diversidade Biológica · ONU', url: 'https://www.cbd.int/convention/text/' }] },
  'dir4-32': { sections: [{ title: 'Acesso à informação pública', text: 'A Lei 12.527/2011 aplica-se aos órgãos e entidades dos três Poderes e aos entes federativos, além de entidades privadas sem fins lucrativos quanto a recursos públicos recebidos. Publicidade é regra e sigilo é exceção. Transparência ativa divulga informações independentemente de pedido. Transparência passiva responde solicitações. O acesso inclui registros, documentos produzidos ou custodiados, informação sobre políticas, despesas e contratos, ressalvadas hipóteses legais de sigilo e dados pessoais.' }, { title: 'Pedido, prazos e recursos', text: 'Pedido não exige motivação e deve identificar requerente e especificar informação. Se o acesso imediato não for possível, o órgão responde em até vinte dias, prorrogáveis por dez mediante justificativa. Negativa deve ser fundamentada e indicar possibilidade de recurso. Informações podem ser classificadas como ultrassecretas, secretas ou reservadas por autoridade competente e prazo legal. O SIC facilita protocolo e acompanhamento.' }], question: 'O cidadão precisa explicar por que deseja uma informação pública?', answer: 'Não. A LAI veda exigência de motivos determinantes para o pedido de acesso.', sources: [{ title: 'Lei 12.527/2011 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2011/lei/l12527.htm' }] },
  'dir4-33': { sections: [{ title: 'LGPD e poder público', text: 'A Lei 13.709/2018 protege direitos de liberdade, privacidade e desenvolvimento da personalidade no tratamento de dados pessoais por pessoas naturais e jurídicas. Dado pessoal identifica ou pode identificar pessoa natural. Dado sensível inclui origem racial, saúde, biometria, religião, opinião política e vida sexual. Princípios incluem finalidade, adequação, necessidade, transparência, segurança, prevenção, não discriminação e responsabilização. O tratamento pelo poder público deve atender finalidade pública, competência legal e interesse público.' }, { title: 'Bases legais, direitos e segurança', text: 'Consentimento é uma das bases legais, mas não a única. Administração pode tratar dados para executar políticas públicas e cumprir obrigações legais, observadas hipóteses dos arts. 7º, 11 e 23. Titular pode solicitar confirmação, acesso, correção e demais direitos compatíveis com o regime público. Controlador define finalidades e meios, operador trata dados em seu nome. Incidentes exigem medidas de segurança e comunicação conforme regulamentação da ANPD. A Lei Estadual 7.692/2002 disciplina processo administrativo estadual, e a Lei 11.088/2020 integra o bloco de recursos hídricos.' }], question: 'Órgão público precisa obter consentimento para todo tratamento de dados pessoais?', answer: 'Não. Pode tratar dados com outras bases legais, como cumprimento de obrigação legal e execução de políticas públicas, desde que respeite finalidade, necessidade, transparência e demais requisitos da LGPD.', sources: [{ title: 'LGPD · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/L13709.htm' }, { title: 'Lei Estadual 7.692/2002 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }, { title: 'Lei Estadual 11.088/2020 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }] },
  'dir4-34': { sections: [{ title: 'Águas subterrâneas em Mato Grosso', text: 'A Lei Estadual 9.612/2011 disciplina conservação e administração das águas subterrâneas em Mato Grosso, articulada à Política Estadual de Recursos Hídricos. A água subterrânea integra aquíferos e pode conectar-se a rios, nascentes e áreas úmidas. Captação por poço, interferência no aquífero e lançamento de contaminantes exigem observância de outorga, licenciamento e padrões de proteção aplicáveis. A gestão deve prevenir superexploração, contaminação e intrusão salina, e monitorar quantidade e qualidade.' }, { title: 'Proteção e fiscalização', text: 'Poços devem ter construção, cadastro, manutenção e fechamento conforme normas técnicas e exigências estaduais. Áreas de recarga e vulnerabilidade requerem proteção preventiva. A autoridade pode impor restrições, monitoramento e medidas de recuperação. O domínio constitucional das águas subterrâneas é estadual, conforme art. 26, I, ressalvadas situações de domínio federal previstas na Constituição. A fiscalização deve considerar uso, aquífero, bacia e efeitos cumulativos.' }], question: 'As águas subterrâneas são, em regra, bens da União?', answer: 'Não. A Constituição inclui entre os bens dos Estados as águas subterrâneas, ressalvadas as hipóteses constitucionais específicas de domínio federal.', sources: [{ title: 'Lei Estadual 9.612/2011 · ALMT', url: 'https://www.al.mt.gov.br/legislacao/' }, { title: 'Constituição Federal, art. 26 · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }] },  'ti0-1.1': { sections: [{ title: 'Segurança cibernética e proteção de dados', text: 'Segurança da informação busca preservar confidencialidade, integridade e disponibilidade. Segurança cibernética protege sistemas, redes e serviços contra ameaças digitais. A LGPD disciplina tratamento de dados pessoais, prevê bases legais, princípios, direitos do titular, deveres de controlador e operador e medidas de segurança. Dados sensíveis recebem proteção reforçada. GDPR é o Regulamento Geral de Proteção de Dados da União Europeia e pode aplicar-se extraterritorialmente em situações previstas, como oferta de bens a pessoas na UE ou monitoramento de seu comportamento. LGPD e GDPR compartilham princípios, mas têm autoridades, bases e regras próprias.' }, { title: 'Zero Trust, firewall, IDS/IPS e WAF', text: 'Zero Trust parte de verificação contínua de identidade, dispositivo e contexto, aplica privilégio mínimo e presume que a rede pode estar comprometida. Firewall controla tráfego por regras de rede e aplicação. IDS detecta e alerta sobre atividade suspeita, enquanto IPS também pode bloquear tráfego. WAF protege aplicações web contra ataques na camada HTTP, como injeção e cross-site scripting, mas não substitui codificação segura nem firewall de rede.' }, { title: 'Vulnerabilidades e pentest', text: 'Análise de vulnerabilidades identifica, classifica e prioriza falhas conhecidas em ativos, com varredura e validação. Pentest simula ataques autorizados para verificar exploração e impacto dentro de escopo definido. Antes do teste, estabeleça autorização formal, ativos, janela, regras de engajamento, dados permitidos e plano de interrupção. Corrigir requer priorização por exposição, criticidade e risco, seguida de reteste e registro.' }], question: 'Qual diferença principal entre IDS e IPS? E um WAF substitui o firewall de rede?', answer: 'IDS detecta e alerta, enquanto IPS pode atuar preventivamente bloqueando tráfego. WAF filtra ataques direcionados à aplicação web e não substitui firewall de rede nem controles de desenvolvimento seguro.', sources: [{ title: 'LGPD · Planalto', url: 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/L13709.htm' }, { title: 'GDPR · EUR-Lex', url: 'https://eur-lex.europa.eu/eli/reg/2016/679/oj' }, { title: 'NIST Cybersecurity Framework', url: 'https://www.nist.gov/cyberframework' }] },
  'ti0-1.2': { sections: [{ title: 'Criptografia simétrica e assimétrica', text: 'Criptografia simétrica usa a mesma chave secreta para cifrar e decifrar. É eficiente para grandes volumes, mas exige distribuir a chave com segurança. Criptografia assimétrica usa par matematicamente relacionado de chaves pública e privada. Pode proteger confidencialidade ao cifrar para o destinatário, ou apoiar assinatura ao assinar com a chave privada e verificar com a pública. Protocolos híbridos usam assimétrica para estabelecer segredo e simétrica para proteger a sessão.' }, { title: 'Hash, assinatura e certificados', text: 'Função hash transforma entrada em resumo de tamanho fixo e deve dificultar encontrar colisões e recuperar a entrada. Hash não é criptografia reversível. Senhas devem ser armazenadas com derivação lenta e salt individual. Assinatura digital combina chave privada e resumo para verificar autoria e integridade, sem garantir sigilo. Certificado digital associa identidade a chave pública e é emitido por autoridade certificadora. Na PKI, autoridade certificadora emite certificados, autoridade de registro valida identidade e cadeia de confiança é verificada até uma raiz confiável.' }], question: 'Um hash permite recuperar o texto original? E uma assinatura digital, por si só, mantém a mensagem secreta?', answer: 'Não. Hash é função unidirecional para verificação e não recuperação. Assinatura demonstra integridade e autenticidade, mas a mensagem pode permanecer pública, salvo se também for cifrada.', sources: [{ title: 'NIST Cryptographic Standards', url: 'https://csrc.nist.gov/projects/cryptographic-standards-and-guidelines' }, { title: 'ICP-Brasil · ITI', url: 'https://www.gov.br/iti/pt-br/assuntos/icp-brasil' }] },
  'ti0-1.3': { sections: [{ title: 'Gestão de riscos', text: 'Risco combina probabilidade e impacto de evento sobre objetivos. O processo identifica ativos, ameaças, vulnerabilidades e controles, estima risco inerente e residual, define apetite e prioriza tratamento. Opções incluem mitigar, evitar, transferir e aceitar formalmente. Registro de riscos indica responsável, prazo, ação e risco residual. Continuidade depende de análise de impacto no negócio, que identifica processos críticos, dependências e efeitos da interrupção.' }, { title: 'BCP, DRP e recuperação', text: 'Business Continuity Plan mantém atividades prioritárias durante crise e define equipes, comunicação, procedimentos alternativos e critérios de retorno. Disaster Recovery Plan recupera tecnologia, dados e infraestrutura após desastre. RTO é o tempo-alvo para restaurar serviço. RPO é a perda máxima aceitável de dados medida em tempo. Backups devem ser isolados, protegidos contra alteração e testados por restauração. Exercícios de mesa e testes técnicos validam planos, fornecedores e comunicação.' }], question: 'Um sistema tem RPO de 4 horas e RTO de 8 horas. O que esses valores indicam?', answer: 'RPO de quatro horas limita a perda de dados a esse intervalo. RTO de oito horas é o prazo-alvo para restaurar o serviço após interrupção.', sources: [{ title: 'NIST Contingency Planning Guide', url: 'https://csrc.nist.gov/pubs/sp/800/34/r1/upd1/final' }, { title: 'NIST Risk Management Framework', url: 'https://csrc.nist.gov/projects/risk-management/about-rmf' }] },};
